commit;

-- MARK: - The reminder job (outside the transaction: pg_cron runs on its own)
-- Supabase: if this line fails, turn on pg_cron under Database → Extensions, then run the rest.
create extension if not exists pg_cron;
select cron.unschedule(jobid) from cron.job where jobname = 'practice-reminders';
select cron.schedule('practice-reminders', '*/5 * * * *', 'select public.queue_practice_reminders()');


-- ################################################################################
-- docs/migrations/2026-10-16-boats.sql
-- ################################################################################
-- Coach version, phase CV3: boats and water sessions (decisions 67, 70; user 2026-10-16).
-- Run once in the Supabase SQL editor, staging first, after 2026-10-16-calendar.sql. Safe to run
-- again.
--
-- What it adds:
--   1. Saved boats: crews a club puts out again and again (decision 70).
--   2. Water sessions: a coach's plan on the river, its boats and who sits where. Seat 1 is bow,
--      the highest seat is stroke, seat 0 is the cox. Nobody logs water metres (decision 54).
--   3. Sending: each rower in a boat is told their boat and seat; it shows on their Feed until
--      the session. Changing a sent boat makes it "Not sent" again until it's re-sent.
--   4. The "boat_seat" alert.

begin;

-- MARK: - Boat types

-- 1x 2x 2- 4- 4+ 4x 8+ (the app shows a real minus sign).
create or replace function boat_rowers(p_type text)
returns int
language sql immutable as $$
  select case p_type when '1x' then 1 when '2x' then 2 when '2-' then 2
                     when '4-' then 4 when '4+' then 4 when '4x' then 4 when '8+' then 8 end;
$$;

create or replace function boat_is_coxed(p_type text)
returns boolean
language sql immutable as $$
  select p_type in ('4+', '8+');
$$;

-- MARK: - 1. Saved boats (decision 70)

create table if not exists saved_boats (
  id         uuid primary key default gen_random_uuid(),
  club_id    uuid not null references clubs on delete cascade,
  name       text not null check (char_length(btrim(name)) between 1 and 40),
  boat_type  text not null check (boat_type in ('1x', '2x', '2-', '4-', '4+', '4x', '8+')),
  rigging    text not null default 'stroke' check (rigging in ('stroke', 'bow')),
  created_by uuid references profiles on delete set null,
  created_at timestamptz not null default now()
);
create index if not exists saved_boats_club on saved_boats (club_id);

create table if not exists saved_boat_seats (
  saved_boat_id uuid not null references saved_boats on delete cascade,
  seat          int not null check (seat between 0 and 8),
  user_id       uuid not null references profiles on delete cascade,
  primary key (saved_boat_id, seat),
  unique (saved_boat_id, user_id)
);

-- MARK: - 2. Water sessions, their boats and seats

create table if not exists water_sessions (
  id          uuid primary key default gen_random_uuid(),
  club_id     uuid not null references clubs on delete cascade,
  -- Who can go comes from this practice's answers, or this race's "Can you race?".
  practice_id uuid references practices on delete set null,
  event_id    uuid references club_events on delete set null,
  title       text not null check (char_length(btrim(title)) between 1 and 80),
  starts_at   timestamptz not null,
  meet_at     text check (meet_at is null or char_length(meet_at) <= 80),
  plan        text check (plan is null or char_length(plan) <= 600),
  created_by  uuid references profiles on delete set null,
  created_at  timestamptz not null default now()
);
create index if not exists water_sessions_club_start on water_sessions (club_id, starts_at);

create table if not exists session_boats (
  id            uuid primary key default gen_random_uuid(),
  session_id    uuid not null references water_sessions on delete cascade,
  position      int not null default 0,
  name          text not null check (char_length(btrim(name)) between 1 and 40),
  boat_type     text not null check (boat_type in ('1x', '2x', '2-', '4-', '4+', '4x', '8+')),
  rigging       text not null default 'stroke' check (rigging in ('stroke', 'bow')),
  saved_boat_id uuid references saved_boats on delete set null,
  -- Null until sent, and again after the crew changes.
  sent_at       timestamptz,
  created_at    timestamptz not null default now()
);
create index if not exists session_boats_session on session_boats (session_id, position);

create table if not exists session_boat_seats (
  boat_id uuid not null references session_boats on delete cascade,
  seat    int not null check (seat between 0 and 8),
  user_id uuid not null references profiles on delete cascade,
  primary key (boat_id, seat),
  unique (boat_id, user_id)
);
create index if not exists session_boat_seats_user on session_boat_seats (user_id);

-- Whether the caller sits in this boat and it has been sent (security definer: no policy loop).
create or replace function in_my_sent_boat(p_boat uuid)
returns boolean
language sql stable security definer set search_path = public as $$
  select exists (
    select 1 from session_boats b
    join session_boat_seats s on s.boat_id = b.id and s.user_id = auth.uid()
    where b.id = p_boat and b.sent_at is not null
  );
$$;

create or replace function in_my_sent_session(p_session uuid)
returns boolean
language sql stable security definer set search_path = public as $$
  select exists (
    select 1 from session_boats b
    join session_boat_seats s on s.boat_id = b.id and s.user_id = auth.uid()
    where b.session_id = p_session and b.sent_at is not null
  );
$$;

alter table saved_boats enable row level security;
alter table saved_boat_seats enable row level security;
alter table water_sessions enable row level security;
alter table session_boats enable row level security;
alter table session_boat_seats enable row level security;

-- Coaches read everything of their club; a rower reads a sent boat they're in, its crew and its
-- session. Every write goes through the functions below.
drop policy if exists read_coach on saved_boats;
create policy read_coach on saved_boats for select to authenticated
  using (is_club_coach(club_id));
drop policy if exists read_coach on saved_boat_seats;
create policy read_coach on saved_boat_seats for select to authenticated
  using (exists (select 1 from saved_boats sb where sb.id = saved_boat_id and is_club_coach(sb.club_id)));
drop policy if exists read_coach_or_crew on water_sessions;
create policy read_coach_or_crew on water_sessions for select to authenticated
  using (is_club_coach(club_id) or in_my_sent_session(id));
drop policy if exists read_coach_or_crew on session_boats;
create policy read_coach_or_crew on session_boats for select to authenticated
  using (in_my_sent_boat(id) or exists (
    select 1 from water_sessions ws where ws.id = session_id and is_club_coach(ws.club_id)
  ));
drop policy if exists read_coach_or_crew on session_boat_seats;
create policy read_coach_or_crew on session_boat_seats for select to authenticated
  using (in_my_sent_boat(boat_id) or exists (
    select 1 from session_boats b join water_sessions ws on ws.id = b.session_id
    where b.id = boat_id and is_club_coach(ws.club_id)
  ));

-- Checks a crew: seats within the boat (a cox only in a coxed boat), each a member of the club,
-- nobody twice. p_seats: [{"seat": 1, "user": "<uuid>"}, …]. Internal.
create or replace function check_crew(p_club uuid, p_type text, p_seats jsonb)
returns void
language plpgsql security definer set search_path = public as $$
declare
  v_item jsonb;
  v_seat int;
begin
  if boat_rowers(p_type) is null then raise exception 'Choose a boat type.'; end if;
  for v_item in select * from jsonb_array_elements(coalesce(p_seats, '[]'::jsonb)) loop
    v_seat := (v_item ->> 'seat')::int;
    if v_seat < 0 or v_seat > boat_rowers(p_type) or (v_seat = 0 and not boat_is_coxed(p_type)) then
      raise exception 'That seat isn''t in this boat.';
    end if;
    if not exists (select 1 from profiles p where p.id = (v_item ->> 'user')::uuid and p.club_id = p_club) then
      raise exception 'Everyone in a boat has to be in your club.';
    end if;
  end loop;
  if (select count(distinct v ->> 'user') from jsonb_array_elements(coalesce(p_seats, '[]'::jsonb)) v)
     <> jsonb_array_length(coalesce(p_seats, '[]'::jsonb)) then
    raise exception 'Someone is in two seats.';
  end if;
end $$;

-- MARK: - Saved boats

create or replace function save_saved_boat(p_saved uuid, p_name text, p_type text, p_rigging text, p_seats jsonb)
returns uuid
language plpgsql security definer set search_path = public as $$
declare
  v_club uuid;
  v_id uuid := p_saved;
begin
  select club_id into v_club from profiles where id = auth.uid();
  if v_club is null or not is_club_coach(v_club) then raise exception 'Only your club''s coaches can save boats.'; end if;
  perform check_crew(v_club, p_type, p_seats);
  if v_id is null then
    insert into saved_boats (club_id, name, boat_type, rigging, created_by)
    values (v_club, btrim(p_name), p_type, coalesce(p_rigging, 'stroke'), auth.uid())
    returning id into v_id;
  else
    update saved_boats set name = btrim(p_name), boat_type = p_type, rigging = coalesce(p_rigging, 'stroke')
    where id = v_id and club_id = v_club;
    if not found then raise exception 'That saved boat no longer exists.'; end if;
    delete from saved_boat_seats where saved_boat_id = v_id;
  end if;
  insert into saved_boat_seats (saved_boat_id, seat, user_id)
    select v_id, (v ->> 'seat')::int, (v ->> 'user')::uuid from jsonb_array_elements(coalesce(p_seats, '[]'::jsonb)) v;
  return v_id;
end $$;

create or replace function delete_saved_boat(p_saved uuid)
returns void
language plpgsql security definer set search_path = public as $$
begin
  delete from saved_boats sb where sb.id = p_saved and is_club_coach(sb.club_id);
end $$;

-- MARK: - Water sessions

-- New (p_session null) or changed. With no practice or race given, the session takes its answers
-- from the club's practice at that time, if there is one.
create or replace function save_water_session(
  p_session uuid, p_title text, p_starts_at timestamptz, p_meet_at text, p_plan text,
  p_practice uuid, p_event uuid
)
returns uuid
language plpgsql security definer set search_path = public as $$
declare
  v_club uuid;
  v_id uuid := p_session;
  v_practice uuid := p_practice;
begin
  select club_id into v_club from profiles where id = auth.uid();
  if v_club is null or not is_club_coach(v_club) then raise exception 'Only your club''s coaches can set water sessions.'; end if;
  if v_practice is null and p_event is null then
    select pr.id into v_practice from practices pr
    where pr.club_id = v_club and not pr.cancelled
      and p_starts_at >= pr.starts_at - interval '30 minutes' and p_starts_at < pr.ends_at
    order by abs(extract(epoch from pr.starts_at - p_starts_at)) limit 1;
  end if;
  if v_id is null then
    insert into water_sessions (club_id, practice_id, event_id, title, starts_at, meet_at, plan, created_by)
    values (v_club, v_practice, p_event, btrim(p_title), p_starts_at,
            nullif(btrim(coalesce(p_meet_at, '')), ''), nullif(btrim(coalesce(p_plan, '')), ''), auth.uid())
    returning id into v_id;
  else
    update water_sessions ws set
      title = btrim(p_title), starts_at = p_starts_at,
      meet_at = nullif(btrim(coalesce(p_meet_at, '')), ''), plan = nullif(btrim(coalesce(p_plan, '')), ''),
      -- A race keeps its race; otherwise the practice follows the time.
      practice_id = case when ws.event_id is not null then ws.practice_id else v_practice end
    where ws.id = v_id and ws.club_id = v_club;
    if not found then raise exception 'That water session no longer exists.'; end if;
  end if;
  return v_id;
end $$;

create or replace function delete_water_session(p_session uuid)
returns void
language plpgsql security definer set search_path = public as $$
begin
  delete from water_sessions ws where ws.id = p_session and is_club_coach(ws.club_id);
end $$;

-- A boat in a session, new (p_boat null) or changed. A sent boat whose name, type, rigging or crew
-- changes goes back to "Not sent". Nobody can be in two boats of one session. p_keep_saved: keep
-- this crew in Saved boats (made the first time, then kept in step); false unlinks it.
create or replace function save_session_boat(
  p_boat uuid, p_session uuid, p_name text, p_type text, p_rigging text, p_seats jsonb, p_keep_saved boolean
)
returns uuid
language plpgsql security definer set search_path = public as $$
declare
  v_session water_sessions;
  v_id uuid := p_boat;
  v_old session_boats;
  v_old_seats jsonb;
  v_new_seats jsonb;
  v_clash text;
  v_saved uuid;
begin
  select * into v_session from water_sessions where id = p_session;
  if v_session.id is null then raise exception 'That water session no longer exists.'; end if;
  if not is_club_coach(v_session.club_id) then raise exception 'Only your club''s coaches can crew boats.'; end if;
  perform check_crew(v_session.club_id, p_type, p_seats);

  select p.display_name || ' is already in ' || b.name into v_clash
  from jsonb_array_elements(coalesce(p_seats, '[]'::jsonb)) v
  join session_boat_seats s on s.user_id = (v ->> 'user')::uuid
  join session_boats b on b.id = s.boat_id and b.session_id = p_session and b.id is distinct from p_boat
  join profiles p on p.id = s.user_id
  limit 1;
  if v_clash is not null then raise exception '%.', v_clash; end if;

  v_new_seats := coalesce((select jsonb_agg(jsonb_build_object('seat', (v ->> 'seat')::int, 'user', v ->> 'user') order by (v ->> 'seat')::int)
                           from jsonb_array_elements(coalesce(p_seats, '[]'::jsonb)) v), '[]'::jsonb);

  if v_id is null then
    insert into session_boats (session_id, position, name, boat_type, rigging)
    values (p_session, coalesce((select max(position) + 1 from session_boats where session_id = p_session), 0),
            btrim(p_name), p_type, coalesce(p_rigging, 'stroke'))
    returning id into v_id;
  else
    select * into v_old from session_boats where id = v_id and session_id = p_session;
    if v_old.id is null then raise exception 'That boat no longer exists.'; end if;
    v_old_seats := coalesce((select jsonb_agg(jsonb_build_object('seat', s.seat, 'user', s.user_id::text) order by s.seat)
                             from session_boat_seats s where s.boat_id = v_id), '[]'::jsonb);
    update session_boats set
      name = btrim(p_name), boat_type = p_type, rigging = coalesce(p_rigging, 'stroke'),
      sent_at = case when v_old.name = btrim(p_name) and v_old.boat_type = p_type
                          and v_old.rigging = coalesce(p_rigging, 'stroke') and v_old_seats = v_new_seats
                     then v_old.sent_at end
    where id = v_id;
    delete from session_boat_seats where boat_id = v_id;
  end if;
  insert into session_boat_seats (boat_id, seat, user_id)
    select v_id, (v ->> 'seat')::int, (v ->> 'user')::uuid from jsonb_array_elements(coalesce(p_seats, '[]'::jsonb)) v;

  if coalesce(p_keep_saved, false) then
    v_saved := save_saved_boat((select saved_boat_id from session_boats where id = v_id), p_name, p_type, p_rigging, p_seats);
    update session_boats set saved_boat_id = v_saved where id = v_id;
  else
    update session_boats set saved_boat_id = null where id = v_id;
  end if;
  return v_id;
end $$;

-- Adds a saved boat to a session. Anyone already in another boat of the session is left out
-- (their seat stays empty); the coach swaps anyone who can't make it afterwards.
create or replace function add_saved_boat(p_saved uuid, p_session uuid)
returns uuid
language plpgsql security definer set search_path = public as $$
declare
  v_session water_sessions;
  v_saved saved_boats;
  v_id uuid;
begin
  select * into v_session from water_sessions where id = p_session;
  select * into v_saved from saved_boats where id = p_saved;
  if v_session.id is null or v_saved.id is null then raise exception 'That boat or session no longer exists.'; end if;
  if not is_club_coach(v_session.club_id) or v_saved.club_id <> v_session.club_id then
    raise exception 'Only your club''s coaches can crew boats.';
  end if;
  insert into session_boats (session_id, position, name, boat_type, rigging, saved_boat_id)
  values (p_session, coalesce((select max(position) + 1 from session_boats where session_id = p_session), 0),
          v_saved.name, v_saved.boat_type, v_saved.rigging, v_saved.id)
  returning id into v_id;
  insert into session_boat_seats (boat_id, seat, user_id)
    select v_id, s.seat, s.user_id from saved_boat_seats s
    where s.saved_boat_id = p_saved
      and not exists (
        select 1 from session_boat_seats o join session_boats b on b.id = o.boat_id
        where b.session_id = p_session and b.id <> v_id and o.user_id = s.user_id
      );
  return v_id;
end $$;

create or replace function delete_session_boat(p_boat uuid)
returns void
language plpgsql security definer set search_path = public as $$
begin
  delete from session_boats b using water_sessions ws
  where b.id = p_boat and ws.id = b.session_id and is_club_coach(ws.club_id);
end $$;

-- MARK: - 3. Sending

-- Sends every boat in the session not sent yet: each rower in it is told their boat and seat.
-- Returns how many rowers were told.
create or replace function send_water_session(p_session uuid)
returns int
language plpgsql security definer set search_path = public as $$
declare
  v_session water_sessions;
  v_boats uuid[];
  v_count int := 0;
begin
  select * into v_session from water_sessions where id = p_session;
  if v_session.id is null then raise exception 'That water session no longer exists.'; end if;
  if not is_club_coach(v_session.club_id) then raise exception 'Only your club''s coaches can send boats.'; end if;

  select coalesce(array_agg(b.id), '{}') into v_boats from session_boats b
  where b.session_id = p_session and b.sent_at is null
    and exists (select 1 from session_boat_seats s where s.boat_id = b.id);
  update session_boats set sent_at = now() where id = any(v_boats);
  select count(*) into v_count from session_boat_seats s where s.boat_id = any(v_boats);

  begin
    insert into notifications (recipient_id, actor_id, kind, club_id, boat_id)
    select s.user_id, auth.uid(), 'boat_seat', v_session.club_id, s.boat_id
    from session_boat_seats s
    where s.boat_id = any(v_boats)
      and s.user_id <> auth.uid()
      and not exists (
        select 1 from blocks bl
        where (bl.blocker_id = s.user_id and bl.blocked_id = auth.uid())
           or (bl.blocker_id = auth.uid() and bl.blocked_id = s.user_id)
      );
  exception when others then
    -- An alert problem must never stop the boats being sent.
    raise warning 'boat alerts: %', sqlerrm;
  end;
  return v_count;
end $$;

-- The caller's sent boats in sessions from p_from on, soonest first (their Feed).
create or replace function my_boats(p_from timestamptz)
returns setof session_boats
language sql stable security definer set search_path = public as $$
  select b.* from session_boats b
  join water_sessions ws on ws.id = b.session_id
  join session_boat_seats s on s.boat_id = b.id and s.user_id = auth.uid()
  where b.sent_at is not null and ws.starts_at >= p_from
  order by ws.starts_at;
$$;

-- MARK: - 4. The alert

do $$
begin
  if to_regclass('public.notifications') is null then
    raise notice 'No notifications table: run 2026-09-26-notifications.sql, then this file again, for boat alerts.';
    return;
  end if;
  alter table notifications add column if not exists boat_id uuid references session_boats on delete cascade;
  alter table notifications drop constraint if exists notifications_kind_check;
  alter table notifications add constraint notifications_kind_check
    check (kind in ('comment', 'reply', 'pb', 'club_post', 'club_invite', 'new_workout',
                    'new_practice', 'practice_changed', 'practice_cancelled', 'practice_reminder', 'new_event',
                    'boat_seat'));
end $$;

-- MARK: - Who may call what

revoke all on function check_crew(uuid, text, jsonb) from public, anon, authenticated;
revoke all on function in_my_sent_boat(uuid) from public, anon;
grant execute on function in_my_sent_boat(uuid) to authenticated;
revoke all on function in_my_sent_session(uuid) from public, anon;
grant execute on function in_my_sent_session(uuid) to authenticated;
revoke all on function save_saved_boat(uuid, text, text, text, jsonb) from public, anon;
grant execute on function save_saved_boat(uuid, text, text, text, jsonb) to authenticated;
revoke all on function delete_saved_boat(uuid) from public, anon;
grant execute on function delete_saved_boat(uuid) to authenticated;
revoke all on function save_water_session(uuid, text, timestamptz, text, text, uuid, uuid) from public, anon;
grant execute on function save_water_session(uuid, text, timestamptz, text, text, uuid, uuid) to authenticated;
revoke all on function delete_water_session(uuid) from public, anon;
grant execute on function delete_water_session(uuid) to authenticated;
revoke all on function save_session_boat(uuid, uuid, text, text, text, jsonb, boolean) from public, anon;
grant execute on function save_session_boat(uuid, uuid, text, text, text, jsonb, boolean) to authenticated;
revoke all on function add_saved_boat(uuid, uuid) from public, anon;
grant execute on function add_saved_boat(uuid, uuid) to authenticated;
revoke all on function delete_session_boat(uuid) from public, anon;
grant execute on function delete_session_boat(uuid) to authenticated;
revoke all on function send_water_session(uuid) from public, anon;
grant execute on function send_water_session(uuid) to authenticated;
revoke all on function my_boats(timestamptz) from public, anon;
grant execute on function my_boats(timestamptz) to authenticated;

commit;


-- ################################################################################
-- docs/migrations/2026-10-17-rigging-and-announcements.sql
-- ################################################################################
-- Custom rigging and announcements (user, 2026-10-17; decisions 74 and 75).
-- Run once in the Supabase SQL editor, staging first, after 2026-10-16-boats.sql. Safe to run
-- again.
--
-- What it adds:
--   1. Custom rigging: a boat can be stroke-rigged, bow-rigged or custom; a custom boat keeps the
--      side of every seat, bow first ('S' stroke side, 'B' bow side): a bucket four is 'SBBS'.
--   2. Announcements: a coach posts a heading and a message to every rower in the club, on their
--      Feed for as long as the coach chooses (24 hours unless they say otherwise), with an alert if
--      they want one. Any coach, the owner or a co-owner can edit or delete one.

begin;

-- MARK: - 1. Custom rigging

alter table saved_boats add column if not exists sides text;
alter table session_boats add column if not exists sides text;
alter table saved_boats drop constraint if exists saved_boats_rigging_check;
alter table saved_boats add constraint saved_boats_rigging_check check (rigging in ('stroke', 'bow', 'custom'));
alter table session_boats drop constraint if exists session_boats_rigging_check;
alter table session_boats add constraint session_boats_rigging_check check (rigging in ('stroke', 'bow', 'custom'));
alter table saved_boats drop constraint if exists saved_boats_sides_valid;
alter table saved_boats add constraint saved_boats_sides_valid check (sides is null or sides ~ '^[SB]{2,8}$');
alter table session_boats drop constraint if exists session_boats_sides_valid;
alter table session_boats add constraint session_boats_sides_valid check (sides is null or sides ~ '^[SB]{2,8}$');

-- A boat's rigging and sides, as they're stored: custom needs a side for every seat of a sweep
-- boat; otherwise there are none. Returns the sides to keep. Internal.
create or replace function checked_sides(p_type text, p_rigging text, p_sides text)
returns text
language plpgsql immutable as $$
begin
  if coalesce(p_rigging, 'stroke') not in ('stroke', 'bow', 'custom') then raise exception 'Choose the rigging.'; end if;
  if p_rigging = 'custom' then
    if p_type in ('1x', '2x', '4x') then raise exception 'Sculling boats have no sides to set.'; end if;
    if p_sides is null or p_sides !~ '^[SB]+$' or char_length(p_sides) <> boat_rowers(p_type) then
      raise exception 'Give every seat a side.';
    end if;
    return p_sides;
  end if;
  return null;
end $$;

drop function if exists save_saved_boat(uuid, text, text, text, jsonb);
create or replace function save_saved_boat(p_saved uuid, p_name text, p_type text, p_rigging text, p_sides text, p_seats jsonb)
returns uuid
language plpgsql security definer set search_path = public as $$
declare
  v_club uuid;
  v_id uuid := p_saved;
  v_sides text := checked_sides(p_type, p_rigging, p_sides);
begin
  select club_id into v_club from profiles where id = auth.uid();
  if v_club is null or not is_club_coach(v_club) then raise exception 'Only your club''s coaches can save boats.'; end if;
  perform check_crew(v_club, p_type, p_seats);
  if v_id is null then
    insert into saved_boats (club_id, name, boat_type, rigging, sides, created_by)
    values (v_club, btrim(p_name), p_type, coalesce(p_rigging, 'stroke'), v_sides, auth.uid())
    returning id into v_id;
  else
    update saved_boats set name = btrim(p_name), boat_type = p_type, rigging = coalesce(p_rigging, 'stroke'), sides = v_sides
    where id = v_id and club_id = v_club;
    if not found then raise exception 'That saved boat no longer exists.'; end if;
    delete from saved_boat_seats where saved_boat_id = v_id;
  end if;
  insert into saved_boat_seats (saved_boat_id, seat, user_id)
    select v_id, (v ->> 'seat')::int, (v ->> 'user')::uuid from jsonb_array_elements(coalesce(p_seats, '[]'::jsonb)) v;
  return v_id;
end $$;

-- As before (2026-10-16-boats.sql), with the sides: a sent boat whose rigging or sides change goes
-- back to Not sent too.
drop function if exists save_session_boat(uuid, uuid, text, text, text, jsonb, boolean);
create or replace function save_session_boat(
  p_boat uuid, p_session uuid, p_name text, p_type text, p_rigging text, p_sides text, p_seats jsonb, p_keep_saved boolean
)
returns uuid
language plpgsql security definer set search_path = public as $$
declare
  v_session water_sessions;
  v_id uuid := p_boat;
  v_old session_boats;
  v_old_seats jsonb;
  v_new_seats jsonb;
  v_clash text;
  v_saved uuid;
  v_sides text := checked_sides(p_type, p_rigging, p_sides);
begin
  select * into v_session from water_sessions where id = p_session;
  if v_session.id is null then raise exception 'That water session no longer exists.'; end if;
  if not is_club_coach(v_session.club_id) then raise exception 'Only your club''s coaches can crew boats.'; end if;
  perform check_crew(v_session.club_id, p_type, p_seats);

  select p.display_name || ' is already in ' || b.name into v_clash
  from jsonb_array_elements(coalesce(p_seats, '[]'::jsonb)) v
  join session_boat_seats s on s.user_id = (v ->> 'user')::uuid
  join session_boats b on b.id = s.boat_id and b.session_id = p_session and b.id is distinct from p_boat
  join profiles p on p.id = s.user_id
  limit 1;
  if v_clash is not null then raise exception '%.', v_clash; end if;

  v_new_seats := coalesce((select jsonb_agg(jsonb_build_object('seat', (v ->> 'seat')::int, 'user', v ->> 'user') order by (v ->> 'seat')::int)
                           from jsonb_array_elements(coalesce(p_seats, '[]'::jsonb)) v), '[]'::jsonb);

  if v_id is null then
    insert into session_boats (session_id, position, name, boat_type, rigging, sides)
    values (p_session, coalesce((select max(position) + 1 from session_boats where session_id = p_session), 0),
            btrim(p_name), p_type, coalesce(p_rigging, 'stroke'), v_sides)
    returning id into v_id;
  else
    select * into v_old from session_boats where id = v_id and session_id = p_session;
    if v_old.id is null then raise exception 'That boat no longer exists.'; end if;
    v_old_seats := coalesce((select jsonb_agg(jsonb_build_object('seat', s.seat, 'user', s.user_id::text) order by s.seat)
                             from session_boat_seats s where s.boat_id = v_id), '[]'::jsonb);
    update session_boats set
      name = btrim(p_name), boat_type = p_type, rigging = coalesce(p_rigging, 'stroke'), sides = v_sides,
      sent_at = case when v_old.name = btrim(p_name) and v_old.boat_type = p_type
                          and v_old.rigging = coalesce(p_rigging, 'stroke') and v_old.sides is not distinct from v_sides
                          and v_old_seats = v_new_seats
                     then v_old.sent_at end
    where id = v_id;
    delete from session_boat_seats where boat_id = v_id;
  end if;
  insert into session_boat_seats (boat_id, seat, user_id)
    select v_id, (v ->> 'seat')::int, (v ->> 'user')::uuid from jsonb_array_elements(coalesce(p_seats, '[]'::jsonb)) v;

  if coalesce(p_keep_saved, false) then
    v_saved := save_saved_boat((select saved_boat_id from session_boats where id = v_id), p_name, p_type, p_rigging, v_sides, p_seats);
    update session_boats set saved_boat_id = v_saved where id = v_id;
  else
    update session_boats set saved_boat_id = null where id = v_id;
  end if;
  return v_id;
end $$;

-- Adding a saved boat keeps its sides too.
create or replace function add_saved_boat(p_saved uuid, p_session uuid)
returns uuid
language plpgsql security definer set search_path = public as $$
declare
  v_session water_sessions;
  v_saved saved_boats;
  v_id uuid;
begin
  select * into v_session from water_sessions where id = p_session;
  select * into v_saved from saved_boats where id = p_saved;
  if v_session.id is null or v_saved.id is null then raise exception 'That boat or session no longer exists.'; end if;
  if not is_club_coach(v_session.club_id) or v_saved.club_id <> v_session.club_id then
    raise exception 'Only your club''s coaches can crew boats.';
  end if;
  insert into session_boats (session_id, position, name, boat_type, rigging, sides, saved_boat_id)
  values (p_session, coalesce((select max(position) + 1 from session_boats where session_id = p_session), 0),
          v_saved.name, v_saved.boat_type, v_saved.rigging, v_saved.sides, v_saved.id)
  returning id into v_id;
  insert into session_boat_seats (boat_id, seat, user_id)
    select v_id, s.seat, s.user_id from saved_boat_seats s
    where s.saved_boat_id = p_saved
      and not exists (
        select 1 from session_boat_seats o join session_boats b on b.id = o.boat_id
        where b.session_id = p_session and b.id <> v_id and o.user_id = s.user_id
      );
  return v_id;
end $$;

-- MARK: - 2. Announcements

create table if not exists announcements (
  id         uuid primary key default gen_random_uuid(),
  club_id    uuid not null references clubs on delete cascade,
  heading    text not null check (char_length(btrim(heading)) between 1 and 80),
  message    text check (message is null or char_length(message) <= 2000),
  -- On rowers' Feeds until then.
  expires_at timestamptz not null,
  created_by uuid references profiles on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index if not exists announcements_club_expiry on announcements (club_id, expires_at desc);

-- Coaches, the owner and co-owners look after a club's announcements.
create or replace function can_manage_announcements(p_club uuid)
returns boolean
language sql stable security definer set search_path = public as $$
  select is_club_coach(p_club) or exists (
    select 1 from profiles p where p.id = auth.uid() and p.club_id = p_club and p.club_role in ('owner', 'co_owner')
  );
$$;

alter table announcements enable row level security;
drop policy if exists read_own_club on announcements;
create policy read_own_club on announcements for select to authenticated
  using (club_id = (select p.club_id from profiles p where p.id = auth.uid()));

-- Post one (coaches). p_alert: every rower in the club also gets "New announcement". Returns its id.
create or replace function post_announcement(p_heading text, p_message text, p_expires_at timestamptz, p_alert boolean)
returns uuid
language plpgsql security definer set search_path = public as $$
declare
  v_club uuid;
  v_id uuid;
begin
  select club_id into v_club from profiles where id = auth.uid();
  if v_club is null or not is_club_coach(v_club) then raise exception 'Only your club''s coaches can post announcements.'; end if;
  if p_expires_at <= now() then raise exception 'Choose a time in the future for it to come off the Feed.'; end if;
  insert into announcements (club_id, heading, message, expires_at, created_by)
  values (v_club, btrim(p_heading), nullif(btrim(coalesce(p_message, '')), ''), p_expires_at, auth.uid())
  returning id into v_id;
  if coalesce(p_alert, false) then
    begin
      insert into notifications (recipient_id, actor_id, kind, club_id, announcement_id)
      select p.id, auth.uid(), 'announcement', v_club, v_id
      from profiles p
      where p.club_id = v_club and p.is_rower and p.id <> auth.uid()
        and not exists (
          select 1 from blocks b
          where (b.blocker_id = p.id and b.blocked_id = auth.uid())
             or (b.blocker_id = auth.uid() and b.blocked_id = p.id)
        );
    exception when others then
      raise warning 'announcement alerts: %', sqlerrm;
    end;
  end if;
  return v_id;
end $$;

create or replace function update_announcement(p_announcement uuid, p_heading text, p_message text, p_expires_at timestamptz)
returns void
language plpgsql security definer set search_path = public as $$
begin
  update announcements a set
    heading = btrim(p_heading), message = nullif(btrim(coalesce(p_message, '')), ''),
    expires_at = p_expires_at, updated_at = now()
  where a.id = p_announcement and can_manage_announcements(a.club_id);
  if not found then raise exception 'Only your club''s coaches and owners can change announcements.'; end if;
end $$;

create or replace function delete_announcement(p_announcement uuid)
returns void
language plpgsql security definer set search_path = public as $$
begin
  delete from announcements a where a.id = p_announcement and can_manage_announcements(a.club_id);
end $$;

-- MARK: - Alerts

do $$
begin
  if to_regclass('public.notifications') is null then
    raise notice 'No notifications table: run 2026-09-26-notifications.sql, then this file again, for announcement alerts.';
    return;
  end if;
  alter table notifications add column if not exists announcement_id uuid references announcements on delete cascade;
  alter table notifications drop constraint if exists notifications_kind_check;
  alter table notifications add constraint notifications_kind_check
    check (kind in ('comment', 'reply', 'pb', 'club_post', 'club_invite', 'new_workout',
                    'new_practice', 'practice_changed', 'practice_cancelled', 'practice_reminder', 'new_event',
                    'boat_seat', 'announcement'));
end $$;

-- MARK: - Who may call what

revoke all on function checked_sides(text, text, text) from public, anon, authenticated;
revoke all on function save_saved_boat(uuid, text, text, text, text, jsonb) from public, anon;
grant execute on function save_saved_boat(uuid, text, text, text, text, jsonb) to authenticated;
revoke all on function save_session_boat(uuid, uuid, text, text, text, text, jsonb, boolean) from public, anon;
grant execute on function save_session_boat(uuid, uuid, text, text, text, text, jsonb, boolean) to authenticated;
revoke all on function can_manage_announcements(uuid) from public, anon;
grant execute on function can_manage_announcements(uuid) to authenticated;
revoke all on function post_announcement(text, text, timestamptz, boolean) from public, anon;
grant execute on function post_announcement(text, text, timestamptz, boolean) to authenticated;
revoke all on function update_announcement(uuid, text, text, timestamptz) from public, anon;
grant execute on function update_announcement(uuid, text, text, timestamptz) to authenticated;
revoke all on function delete_announcement(uuid) from public, anon;
grant execute on function delete_announcement(uuid) to authenticated;

commit;


-- ################################################################################
-- docs/migrations/2026-10-18-coxed-quad.sql
-- ################################################################################
-- Rowing Pals: a coxed quad (decision 77, 2026-10-18).
-- Run on staging after 2026-10-17-rigging-and-announcements.sql. Safe to run twice.
--
-- Boat types become 1x 2x 2- 4- 4+ 4x 4x+ 8+: the coxed quad has four scullers and a cox.

-- MARK: - Boat types

create or replace function boat_rowers(p_type text)
returns int
language sql immutable as $$
  select case p_type when '1x' then 1 when '2x' then 2 when '2-' then 2
                     when '4-' then 4 when '4+' then 4 when '4x' then 4 when '4x+' then 4 when '8+' then 8 end;
$$;

create or replace function boat_is_coxed(p_type text)
returns boolean
language sql immutable as $$
  select p_type in ('4+', '4x+', '8+');
$$;

alter table saved_boats drop constraint if exists saved_boats_boat_type_check;
alter table saved_boats add constraint saved_boats_boat_type_check
  check (boat_type in ('1x', '2x', '2-', '4-', '4+', '4x', '4x+', '8+'));
alter table session_boats drop constraint if exists session_boats_boat_type_check;
alter table session_boats add constraint session_boats_boat_type_check
  check (boat_type in ('1x', '2x', '2-', '4-', '4+', '4x', '4x+', '8+'));

-- MARK: - Sides

-- As in 2026-10-17, with the coxed quad among the sculling boats. Internal (its grants are kept).
create or replace function checked_sides(p_type text, p_rigging text, p_sides text)
returns text
language plpgsql immutable as $$
begin
  if coalesce(p_rigging, 'stroke') not in ('stroke', 'bow', 'custom') then raise exception 'Choose the rigging.'; end if;
  if p_rigging = 'custom' then
    if p_type in ('1x', '2x', '4x', '4x+') then raise exception 'Sculling boats have no sides to set.'; end if;
    if p_sides is null or p_sides !~ '^[SB]+$' or char_length(p_sides) <> boat_rowers(p_type) then
      raise exception 'Give every seat a side.';
    end if;
    return p_sides;
  end if;
  return null;
end $$;


-- ################################################################################
-- docs/migrations/2026-10-18-cox-side.sql
-- ################################################################################
-- Rowing Pals: Cox as a side (decision 78, 2026-10-18).
-- Run on staging after 2026-10-16-coach-version.sql. Safe to run twice.
--
-- The side picker at sign-up and in Edit profile is Stroke side · Bow side · Both · Cox, so a
-- profile's side may now be 'cox'. Coaches see it when crewing: coxes first for the cox seat, and
-- a Cox tag in a rowing seat.

alter table profiles drop constraint if exists profiles_side_valid;
alter table profiles add constraint profiles_side_valid
  check (side is null or side in ('stroke', 'bow', 'both', 'cox'));


-- ################################################################################
-- docs/migrations/2026-10-18-water-session-ends.sql
-- ################################################################################
-- Rowing Pals: water sessions end, and rowers see them (decision 79, 2026-10-18).
-- Run on staging after 2026-10-16-boats.sql. Safe to run twice.
--
-- 1. A water session has an end (Starts and Ends, like a practice). Existing sessions end two hours
--    after they start. The rower's Feed shows a boat until its session ends.
-- 2. Owners, co-owners and admins read the club's water sessions and boats, as coaches already do,
--    for "Whole club" in their Calendar. Rowers still read only sent boats they're in.

begin;

-- MARK: - 1. Ends

alter table water_sessions add column if not exists ends_at timestamptz;
update water_sessions set ends_at = starts_at + interval '2 hours' where ends_at is null;

-- A session saved without an end (an older app) ends two hours after it starts; an end must come
-- after the start.
create or replace function water_session_default_end()
returns trigger
language plpgsql as $$
begin
  new.ends_at := coalesce(new.ends_at, new.starts_at + interval '2 hours');
  if new.ends_at <= new.starts_at then raise exception 'A session has to end after it starts.'; end if;
  return new;
end $$;

drop trigger if exists water_sessions_default_end on water_sessions;
create trigger water_sessions_default_end before insert or update of starts_at, ends_at on water_sessions
  for each row execute function water_session_default_end();

alter table water_sessions alter column ends_at set not null;

-- As in 2026-10-16, with the end. The old signature stays for an app that doesn't send one yet.
create or replace function save_water_session(
  p_session uuid, p_title text, p_starts_at timestamptz, p_ends_at timestamptz, p_meet_at text, p_plan text,
  p_practice uuid, p_event uuid
)
returns uuid
language plpgsql security definer set search_path = public as $$
declare
  v_club uuid;
  v_id uuid := p_session;
  v_practice uuid := p_practice;
  v_ends timestamptz := coalesce(p_ends_at, p_starts_at + interval '2 hours');
begin
  select club_id into v_club from profiles where id = auth.uid();
  if v_club is null or not is_club_coach(v_club) then raise exception 'Only your club''s coaches can set water sessions.'; end if;
  if v_ends <= p_starts_at then raise exception 'A session has to end after it starts.'; end if;
  if v_practice is null and p_event is null then
    select pr.id into v_practice from practices pr
    where pr.club_id = v_club and not pr.cancelled
      and p_starts_at >= pr.starts_at - interval '30 minutes' and p_starts_at < pr.ends_at
    order by abs(extract(epoch from pr.starts_at - p_starts_at)) limit 1;
  end if;
  if v_id is null then
    insert into water_sessions (club_id, practice_id, event_id, title, starts_at, ends_at, meet_at, plan, created_by)
    values (v_club, v_practice, p_event, btrim(p_title), p_starts_at, v_ends,
            nullif(btrim(coalesce(p_meet_at, '')), ''), nullif(btrim(coalesce(p_plan, '')), ''), auth.uid())
    returning id into v_id;
  else
    update water_sessions ws set
      title = btrim(p_title), starts_at = p_starts_at, ends_at = v_ends,
      meet_at = nullif(btrim(coalesce(p_meet_at, '')), ''), plan = nullif(btrim(coalesce(p_plan, '')), ''),
      -- A race keeps its race; otherwise the practice follows the time.
      practice_id = case when ws.event_id is not null then ws.practice_id else v_practice end
    where ws.id = v_id and ws.club_id = v_club;
    if not found then raise exception 'That water session no longer exists.'; end if;
  end if;
  return v_id;
end $$;

-- The rower's sent boats whose session hasn't ended by p_from (was: hadn't started).
create or replace function my_boats(p_from timestamptz)
returns setof session_boats
language sql stable security definer set search_path = public as $$
  select b.* from session_boats b
  join water_sessions ws on ws.id = b.session_id
  join session_boat_seats s on s.boat_id = b.id and s.user_id = auth.uid()
  where b.sent_at is not null and ws.ends_at >= p_from
  order by ws.starts_at;
$$;

-- MARK: - 2. Who reads the club's water sessions

-- Coaches, and the owner, co-owners and admins (decision 79).
create or replace function can_see_club_water(p_club uuid)
returns boolean
language sql stable security definer set search_path = public as $$
  select is_club_coach(p_club) or is_club_manager(p_club, 'admin');
$$;

drop policy if exists read_coach_or_crew on water_sessions;
create policy read_coach_or_crew on water_sessions for select to authenticated
  using (can_see_club_water(club_id) or in_my_sent_session(id));
drop policy if exists read_coach_or_crew on session_boats;
create policy read_coach_or_crew on session_boats for select to authenticated
  using (in_my_sent_boat(id) or exists (
    select 1 from water_sessions ws where ws.id = session_id and can_see_club_water(ws.club_id)
  ));
drop policy if exists read_coach_or_crew on session_boat_seats;
create policy read_coach_or_crew on session_boat_seats for select to authenticated
  using (in_my_sent_boat(boat_id) or exists (
    select 1 from session_boats b join water_sessions ws on ws.id = b.session_id
    where b.id = boat_id and can_see_club_water(ws.club_id)
  ));

revoke all on function save_water_session(uuid, text, timestamptz, timestamptz, text, text, uuid, uuid) from public, anon;
grant execute on function save_water_session(uuid, text, timestamptz, timestamptz, text, text, uuid, uuid) to authenticated;
revoke all on function can_see_club_water(uuid) from public, anon;
grant execute on function can_see_club_water(uuid) to authenticated;
revoke all on function water_session_default_end() from public, anon, authenticated;

commit;

-- Tell the API about the new save_water_session at once (otherwise the app can report "Could not
-- find the function … in the schema cache" until it refreshes by itself).
notify pgrst, 'reload schema';


-- ################################################################################
-- docs/migrations/2026-10-18-usernames.sql
-- ################################################################################
-- Rowing Pals: usernames (decision 85, 2026-10-18).
-- Run on staging after the earlier migrations. Safe to run twice.
--
-- Every account has a unique username — lower case, 3–20 of a–z 0–9 . _, not starting or ending
-- with a dot — shown as @username and used to sign in instead of the email. Accounts made before
-- this choose one the next time they open the app. Signing in with a username goes through the
-- username-auth Edge Function, which looks the email up on the server: nobody can turn a username
-- into an email address.

alter table profiles add column if not exists username text;

alter table profiles drop constraint if exists profiles_username_valid;
alter table profiles add constraint profiles_username_valid
  check (username is null or username ~ '^[a-z0-9_]([a-z0-9._]{1,18})[a-z0-9_]$');

create unique index if not exists profiles_username_unique on profiles (username);

-- Whether a username can be taken (before an account exists, at sign-up; the caller's own counts
-- as free).
create or replace function username_available(p_username text)
returns boolean
language sql stable security definer set search_path = public as $$
  select lower(btrim(p_username)) ~ '^[a-z0-9_]([a-z0-9._]{1,18})[a-z0-9_]$'
     and not exists (
       select 1 from profiles
       where username = lower(btrim(p_username)) and (auth.uid() is null or id <> auth.uid())
     );
$$;

-- Sets the caller's username, with plain words for what's wrong.
create or replace function set_username(p_username text)
returns text
language plpgsql security definer set search_path = public as $$
declare
  v text := lower(btrim(coalesce(p_username, '')));
begin
  if auth.uid() is null then raise exception 'Sign in first.'; end if;
  if char_length(v) < 3 then raise exception 'A username needs at least 3 characters.'; end if;
  if char_length(v) > 20 then raise exception 'A username can be at most 20 characters.'; end if;
  if v !~ '^[a-z0-9._]+$' then raise exception 'Use only letters, numbers, full stops and underscores.'; end if;
  if v ~ '^\.' or v ~ '\.$' then raise exception 'A username can''t start or end with a full stop.'; end if;
  if exists (select 1 from profiles where username = v and id <> auth.uid()) then
    raise exception 'That username is taken.';
  end if;
  update profiles set username = v where id = auth.uid();
  if not found then raise exception 'Finish setting up your account first.'; end if;
  return v;
end $$;

revoke all on function username_available(text) from public;
grant execute on function username_available(text) to anon, authenticated;
revoke all on function set_username(text) from public, anon;
grant execute on function set_username(text) to authenticated;

notify pgrst, 'reload schema';


-- ################################################################################
-- docs/migrations/2026-10-18-boat-colours.sql
-- ################################################################################
-- Boat colours (user, 2026-10-18; decision 87).
-- Run once in the Supabase SQL editor, staging first, after 2026-10-17-rigging-and-announcements.sql
-- and 2026-10-18-coxed-quad.sql. Safe to run again.
--
-- A coach can colour a boat (any colour, kept as '#RRGGBB') so it's easy to pick out: on the
-- coach's screens and on the rower's Feed and Calendar. A saved boat keeps its colour, and adding
-- it to a session brings the colour with it. Changing only the colour of a sent boat doesn't make
-- it Not sent: nothing the crew needs to know has changed.

begin;

alter table saved_boats add column if not exists colour text;
alter table session_boats add column if not exists colour text;
alter table saved_boats drop constraint if exists saved_boats_colour_valid;
alter table saved_boats add constraint saved_boats_colour_valid check (colour is null or colour ~ '^#[0-9A-F]{6}$');
alter table session_boats drop constraint if exists session_boats_colour_valid;
alter table session_boats add constraint session_boats_colour_valid check (colour is null or colour ~ '^#[0-9A-F]{6}$');

-- A colour as it's stored: '#RRGGBB' in capitals, or null for none. Internal.
create or replace function checked_colour(p_colour text)
returns text
language plpgsql immutable as $$
declare
  v text := upper(nullif(btrim(coalesce(p_colour, '')), ''));
begin
  if v is null then return null; end if;
  if v !~ '^#[0-9A-F]{6}$' then raise exception 'Choose the boat''s colour again.'; end if;
  return v;
end $$;

-- As 2026-10-17-rigging-and-announcements.sql, with the colour.
drop function if exists save_saved_boat(uuid, text, text, text, text, jsonb);
create or replace function save_saved_boat(
  p_saved uuid, p_name text, p_type text, p_rigging text, p_sides text, p_seats jsonb, p_colour text default null
)
returns uuid
language plpgsql security definer set search_path = public as $$
declare
  v_club uuid;
  v_id uuid := p_saved;
  v_sides text := checked_sides(p_type, p_rigging, p_sides);
  v_colour text := checked_colour(p_colour);
begin
  select club_id into v_club from profiles where id = auth.uid();
  if v_club is null or not is_club_coach(v_club) then raise exception 'Only your club''s coaches can save boats.'; end if;
  perform check_crew(v_club, p_type, p_seats);
  if v_id is null then
    insert into saved_boats (club_id, name, boat_type, rigging, sides, colour, created_by)
    values (v_club, btrim(p_name), p_type, coalesce(p_rigging, 'stroke'), v_sides, v_colour, auth.uid())
    returning id into v_id;
  else
    update saved_boats set name = btrim(p_name), boat_type = p_type, rigging = coalesce(p_rigging, 'stroke'),
                           sides = v_sides, colour = v_colour
    where id = v_id and club_id = v_club;
    if not found then raise exception 'That saved boat no longer exists.'; end if;
    delete from saved_boat_seats where saved_boat_id = v_id;
  end if;
  insert into saved_boat_seats (saved_boat_id, seat, user_id)
    select v_id, (v ->> 'seat')::int, (v ->> 'user')::uuid from jsonb_array_elements(coalesce(p_seats, '[]'::jsonb)) v;
  return v_id;
end $$;

-- As 2026-10-17-rigging-and-announcements.sql, with the colour (which doesn't un-send a boat).
drop function if exists save_session_boat(uuid, uuid, text, text, text, text, jsonb, boolean);
create or replace function save_session_boat(
  p_boat uuid, p_session uuid, p_name text, p_type text, p_rigging text, p_sides text, p_seats jsonb, p_keep_saved boolean,
  p_colour text default null
)
returns uuid
language plpgsql security definer set search_path = public as $$
declare
  v_session water_sessions;
  v_id uuid := p_boat;
  v_old session_boats;
  v_old_seats jsonb;
  v_new_seats jsonb;
  v_clash text;
  v_saved uuid;
  v_sides text := checked_sides(p_type, p_rigging, p_sides);
  v_colour text := checked_colour(p_colour);
begin
  select * into v_session from water_sessions where id = p_session;
  if v_session.id is null then raise exception 'That water session no longer exists.'; end if;
  if not is_club_coach(v_session.club_id) then raise exception 'Only your club''s coaches can crew boats.'; end if;
  perform check_crew(v_session.club_id, p_type, p_seats);

  select p.display_name || ' is already in ' || b.name into v_clash
  from jsonb_array_elements(coalesce(p_seats, '[]'::jsonb)) v
  join session_boat_seats s on s.user_id = (v ->> 'user')::uuid
  join session_boats b on b.id = s.boat_id and b.session_id = p_session and b.id is distinct from p_boat
  join profiles p on p.id = s.user_id
  limit 1;
  if v_clash is not null then raise exception '%.', v_clash; end if;

  v_new_seats := coalesce((select jsonb_agg(jsonb_build_object('seat', (v ->> 'seat')::int, 'user', v ->> 'user') order by (v ->> 'seat')::int)
                           from jsonb_array_elements(coalesce(p_seats, '[]'::jsonb)) v), '[]'::jsonb);

  if v_id is null then
    insert into session_boats (session_id, position, name, boat_type, rigging, sides, colour)
    values (p_session, coalesce((select max(position) + 1 from session_boats where session_id = p_session), 0),
            btrim(p_name), p_type, coalesce(p_rigging, 'stroke'), v_sides, v_colour)
    returning id into v_id;
  else
    select * into v_old from session_boats where id = v_id and session_id = p_session;
    if v_old.id is null then raise exception 'That boat no longer exists.'; end if;
    v_old_seats := coalesce((select jsonb_agg(jsonb_build_object('seat', s.seat, 'user', s.user_id::text) order by s.seat)
                             from session_boat_seats s where s.boat_id = v_id), '[]'::jsonb);
    update session_boats set
      name = btrim(p_name), boat_type = p_type, rigging = coalesce(p_rigging, 'stroke'), sides = v_sides, colour = v_colour,
      sent_at = case when v_old.name = btrim(p_name) and v_old.boat_type = p_type
                          and v_old.rigging = coalesce(p_rigging, 'stroke') and v_old.sides is not distinct from v_sides
                          and v_old_seats = v_new_seats
                     then v_old.sent_at end
    where id = v_id;
    delete from session_boat_seats where boat_id = v_id;
  end if;
  insert into session_boat_seats (boat_id, seat, user_id)
    select v_id, (v ->> 'seat')::int, (v ->> 'user')::uuid from jsonb_array_elements(coalesce(p_seats, '[]'::jsonb)) v;

  if coalesce(p_keep_saved, false) then
    v_saved := save_saved_boat((select saved_boat_id from session_boats where id = v_id), p_name, p_type, p_rigging, v_sides, p_seats, v_colour);
    update session_boats set saved_boat_id = v_saved where id = v_id;
  else
    update session_boats set saved_boat_id = null where id = v_id;
  end if;
  return v_id;
end $$;

-- Adding a saved boat brings its colour too.
create or replace function add_saved_boat(p_saved uuid, p_session uuid)
returns uuid
language plpgsql security definer set search_path = public as $$
declare
  v_session water_sessions;
  v_saved saved_boats;
  v_id uuid;
begin
  select * into v_session from water_sessions where id = p_session;
  select * into v_saved from saved_boats where id = p_saved;
  if v_session.id is null or v_saved.id is null then raise exception 'That boat or session no longer exists.'; end if;
  if not is_club_coach(v_session.club_id) or v_saved.club_id <> v_session.club_id then
    raise exception 'Only your club''s coaches can crew boats.';
  end if;
  insert into session_boats (session_id, position, name, boat_type, rigging, sides, colour, saved_boat_id)
  values (p_session, coalesce((select max(position) + 1 from session_boats where session_id = p_session), 0),
          v_saved.name, v_saved.boat_type, v_saved.rigging, v_saved.sides, v_saved.colour, v_saved.id)
  returning id into v_id;
  insert into session_boat_seats (boat_id, seat, user_id)
    select v_id, s.seat, s.user_id from saved_boat_seats s
    where s.saved_boat_id = p_saved
      and not exists (
        select 1 from session_boat_seats o join session_boats b on b.id = o.boat_id
        where b.session_id = p_session and b.id <> v_id and o.user_id = s.user_id
      );
  return v_id;
end $$;

revoke all on function checked_colour(text) from public, anon, authenticated;
revoke all on function save_saved_boat(uuid, text, text, text, text, jsonb, text) from public, anon;
grant execute on function save_saved_boat(uuid, text, text, text, text, jsonb, text) to authenticated;
revoke all on function save_session_boat(uuid, uuid, text, text, text, text, jsonb, boolean, text) from public, anon;
grant execute on function save_session_boat(uuid, uuid, text, text, text, text, jsonb, boolean, text) to authenticated;
revoke all on function add_saved_boat(uuid, uuid) from public, anon;
grant execute on function add_saved_boat(uuid, uuid) to authenticated;

commit;

-- The API sees the new column and functions straight away.
notify pgrst, 'reload schema';


-- ################################################################################
-- docs/migrations/2026-10-18-rank-change-alerts.sql
-- ################################################################################
-- Rank-change alerts (v1.1, user 2026-10-18; decision 89).
-- Run once in the Supabase SQL editor, staging first, after 2026-10-17-rigging-and-announcements.sql.
-- Safe to run again. pg_cron must be on (Database → Extensions), as for practice reminders.
--
-- Every Monday at 08:00 (UK time) each rower who rowed last week (Monday to Sunday) and whose place
-- on the club's weekly metres board moved gets one alert: "You finished 3rd of 12 senior men last
-- week, up 2 places." Their board is the one Rankings opens on: their own gender and level in their
-- club (the whole club when they haven't given a gender), counting only metres on the leaderboards,
-- erg only. Up or down both count; no alert when their place didn't change or they didn't row, or
-- when they're the only one in their group. At most one a week. Settings → Notifications → Rank
-- changes (on unless turned off).

begin;

alter table notification_settings add column if not exists rank_changes boolean not null default true;

-- One rower's week on their board: what the alert says. Kept so the alert can be composed, and so
-- each rower is told at most once a week.
create table if not exists rank_changes (
  id            uuid primary key default gen_random_uuid(),
  user_id       uuid not null references profiles on delete cascade,
  week_start    date not null,
  rank          int not null check (rank > 0),
  previous_rank int check (previous_rank > 0),
  group_size    int not null check (group_size > 1),
  group_label   text not null,
  metres        int not null check (metres > 0),
  created_at    timestamptz not null default now(),
  unique (user_id, week_start)
);
alter table rank_changes enable row level security;
drop policy if exists read_own on rank_changes;
create policy read_own on rank_changes for select to authenticated using (user_id = auth.uid());

do $$
begin
  alter table notifications add column if not exists rank_change_id uuid references rank_changes on delete cascade;
  alter table notifications drop constraint if exists notifications_kind_check;
  alter table notifications add constraint notifications_kind_check
    check (kind in ('comment', 'reply', 'pb', 'club_post', 'club_invite', 'new_workout',
                    'new_practice', 'practice_changed', 'practice_cancelled', 'practice_reminder', 'new_event',
                    'boat_seat', 'announcement', 'rank_change'));
end $$;

-- Every rower's place on their own weekly metres board for the week starting p_week (a Monday):
-- metres on the leaderboards from p_week to the Sunday, ranked within their club and group, most
-- first (ties: the earlier account first). Only rowers with metres that week are ranked. Internal.
create or replace function weekly_ranks(p_week date)
returns table (user_id uuid, rank int, group_size int, group_label text, metres int)
language sql stable security definer set search_path = public as $$
  with totals as (
    select p.id, p.club_id, p.gender, p.category, p.created_at,
           coalesce(sum(d.ranked_erg_distance_m), 0)::int as metres
    from profiles p
    left join daily_totals d on d.user_id = p.id and d.day >= p_week and d.day < p_week + 7
    where p.club_id is not null and p.is_rower
    group by p.id
  )
  select u.id,
         (select count(*) from totals o
          where o.club_id = u.club_id and o.metres > 0
            and (u.gender is null or (o.gender = u.gender and o.category = u.category))
            and (o.metres > u.metres or (o.metres = u.metres and (o.created_at, o.id) < (u.created_at, u.id))))::int + 1,
         (select count(*) from totals o
          where o.club_id = u.club_id and o.metres > 0
            and (u.gender is null or (o.gender = u.gender and o.category = u.category)))::int,
         case
           when u.gender is null then 'rowers in your club'
           else u.category::text || ' ' || case u.gender when 'M' then 'men' else 'women' end
         end,
         u.metres
  from totals u
  where u.metres > 0
$$;

-- Monday, 08:00 UK time: last week's places against the week before's; one alert to each rower whose
-- place moved (or who's on the board after a week off). Runs every hour on Mondays and acts once.
-- To try it on another day (testing): select queue_rank_change_alerts(true); — still once a week each.
drop function if exists queue_rank_change_alerts();
create or replace function queue_rank_change_alerts(p_now boolean default false)
returns void
language plpgsql security definer set search_path = public as $$
declare
  v_local timestamp := now() at time zone 'Europe/London';
  v_this_monday date := (v_local::date - (extract(isodow from v_local)::int - 1));
  v_last date := v_this_monday - 7;
begin
  if not p_now and (extract(isodow from v_local) <> 1 or extract(hour from v_local) <> 8) then return; end if;

  with last_week as (select * from weekly_ranks(v_last)),
       week_before as (select * from weekly_ranks(v_last - 7)),
       moved as (
         insert into rank_changes (user_id, week_start, rank, previous_rank, group_size, group_label, metres)
         select l.user_id, v_last, l.rank, b.rank, l.group_size, l.group_label, l.metres
         from last_week l
         left join week_before b on b.user_id = l.user_id
         left join notification_settings ns on ns.user_id = l.user_id
         where l.group_size > 1
           and b.rank is distinct from l.rank
           and coalesce(ns.rank_changes, true)
         on conflict (user_id, week_start) do nothing
         returning id, user_id
       )
  insert into notifications (recipient_id, actor_id, kind, rank_change_id)
  select m.user_id, m.user_id, 'rank_change', m.id from moved m;
end $$;

revoke all on function weekly_ranks(date) from public, anon, authenticated;
revoke all on function queue_rank_change_alerts(boolean) from public, anon, authenticated;

commit;

-- The API sees the new column straight away.
notify pgrst, 'reload schema';

-- MARK: - The weekly job (outside the transaction: pg_cron runs on its own)
create extension if not exists pg_cron;
select cron.unschedule(jobid) from cron.job where jobname = 'rank-change-alerts';
select cron.schedule('rank-change-alerts', '5 * * * 1', 'select public.queue_rank_change_alerts()');


-- ################################################################################
-- docs/migrations/2026-10-18-crew-tags.sql
-- ################################################################################
-- Crew tagging (v1.1, user 2026-10-18; decision 90).
-- Run once in the Supabase SQL editor, staging first. Safe to run again.
--
-- The person posting a session can tag the clubmates they trained with; the post then shows
-- "with Sam, Joe". Only clubmates who row can be tagged (not yourself, not coach-only accounts).
-- The poster sets the tags when posting and can change them afterwards; anyone tagged can remove
-- themselves. Tags are only a line on the post: no alert, nothing on the tagged rower's profile,
-- and their own metres never change. Who can see a post's tags is who can see the post.

begin;

-- One tagged person on one post. Its own id, so the API doesn't treat it as a second way from a
-- session to a profile (sessions → profiles stays the author).
create table if not exists session_tags (
  id         uuid primary key default gen_random_uuid(),
  session_id uuid not null references sessions on delete cascade,
  user_id    uuid not null references profiles on delete cascade,
  created_at timestamptz not null default now(),
  unique (session_id, user_id)
);
create index if not exists session_tags_user_idx on session_tags (user_id);
alter table session_tags enable row level security;

-- Seen by whoever can see the post (the sessions policies decide, inside this check).
drop policy if exists read_with_post on session_tags;
create policy read_with_post on session_tags for select to authenticated
  using (exists (select 1 from sessions s where s.id = session_tags.session_id));

-- The poster sets who they trained with: exactly these people, clubmates who row. Replaces the
-- post's tags; an empty list clears them.
create or replace function set_session_tags(p_session uuid, p_users uuid[])
returns void
language plpgsql security definer set search_path = public as $$
declare
  v_owner uuid;
  v_club uuid;
  v_users uuid[] := array(select distinct u from unnest(coalesce(p_users, '{}')) u where u is not null);
begin
  select user_id into v_owner from sessions where id = p_session;
  if v_owner is null then raise exception 'That post no longer exists.'; end if;
  if v_owner <> auth.uid() then raise exception 'Only the person who posted it can tag people.'; end if;
  if cardinality(v_users) > 20 then raise exception 'Tag up to 20 people.'; end if;
  if cardinality(v_users) > 0 then
    select club_id into v_club from profiles where id = v_owner;
    if v_club is null then raise exception 'Join a club to tag the people you trained with.'; end if;
    if exists (
      select 1 from unnest(v_users) u
      where u = v_owner
         or not exists (select 1 from profiles p where p.id = u and p.club_id = v_club and p.is_rower)
    ) then
      raise exception 'You can tag clubmates who row.';
    end if;
  end if;
  delete from session_tags where session_id = p_session and not (user_id = any(v_users));
  insert into session_tags (session_id, user_id)
    select p_session, u from unnest(v_users) u
  on conflict (session_id, user_id) do nothing;
end $$;

-- Someone tagged takes themselves off a post. The poster isn't told.
create or replace function remove_my_tag(p_session uuid)
returns void
language plpgsql security definer set search_path = public as $$
begin
  delete from session_tags where session_id = p_session and user_id = auth.uid();
end $$;

revoke all on function set_session_tags(uuid, uuid[]) from public, anon;
grant execute on function set_session_tags(uuid, uuid[]) to authenticated;
revoke all on function remove_my_tag(uuid) from public, anon;
grant execute on function remove_my_tag(uuid) to authenticated;

commit;

-- The API sees the new table and functions straight away.
notify pgrst, 'reload schema';


-- ################################################################################
-- docs/migrations/2026-10-18-challenges-and-erg-events.sql
-- ################################################################################
-- Challenges and erg events (v1.2, user 2026-10-18; decision 91).
-- Run once in the Supabase SQL editor, staging first. Safe to run again.
--
-- Challenges: a club's coaches, owner, co-owners and admins set one, and every rower in the club is
-- in it. Three kinds, all on erg metres on the leaderboards (as Rankings) between two days:
--   target     — each rower aims for the same number of metres ("Row 100km in November");
--   club_total — the club together towards one number ("2,000km as a club this term");
--   squads     — two or more squads race on metres per rower.
-- Erg events: a set piece (a distance or a time) rowed in a window ("Club 2k day, Sat 9–12"). A rower
-- posting a matching piece during it (or up to six hours after) can count it for the event; the
-- event's board shows each rower's best.
--
-- The new tables link only to their club: who set them is kept as a plain id, so the API doesn't
-- gain a second way between clubs and profiles (see 2026-10-04-club-tests.sql).

begin;

-- Coaches, the owner, co-owners and admins of the club.
create or replace function can_set_challenges(p_club uuid)
returns boolean
language sql stable security definer set search_path = public as $$
  select is_club_coach(p_club) or exists (
    select 1 from profiles p where p.id = auth.uid() and p.club_id = p_club
      and p.club_role in ('owner', 'co_owner', 'admin')
  );
$$;

-- MARK: - Challenges

create table if not exists challenges (
  id         uuid primary key default gen_random_uuid(),
  club_id    uuid not null references clubs on delete cascade,
  kind       text not null check (kind in ('target', 'club_total', 'squads')),
  title      text not null check (char_length(btrim(title)) between 1 and 60),
  target_m   int check (target_m between 1000 and 100000000),
  squad_ids  uuid[] not null default '{}',
  starts_on  date not null,
  ends_on    date not null,
  created_by uuid,
  created_at timestamptz not null default now(),
  constraint challenges_dates check (ends_on >= starts_on and ends_on - starts_on <= 366),
  constraint challenges_shape check (
    (kind in ('target', 'club_total') and target_m is not null)
    or (kind = 'squads' and cardinality(squad_ids) >= 2)
  )
);
create index if not exists challenges_club_idx on challenges (club_id, ends_on desc);
alter table challenges enable row level security;
drop policy if exists read_own_club on challenges;
create policy read_own_club on challenges for select to authenticated
  using (club_id = (select p.club_id from profiles p where p.id = auth.uid()));

-- Saves a challenge, new (p_id null) or changed; returns its id.
create or replace function save_challenge(
  p_id uuid, p_kind text, p_title text, p_target_m int, p_squads uuid[], p_starts date, p_ends date
)
returns uuid
language plpgsql security definer set search_path = public as $$
declare
  v_club uuid;
  v_id uuid := p_id;
  v_squads uuid[] := array(select distinct s from unnest(coalesce(p_squads, '{}')) s where s is not null);
begin
  select club_id into v_club from profiles where id = auth.uid();
  if v_club is null or not can_set_challenges(v_club) then
    raise exception 'Only your club''s coaches, owner, co-owners and admins can set challenges.';
  end if;
  if coalesce(p_kind, '') not in ('target', 'club_total', 'squads') then raise exception 'Choose the kind of challenge.'; end if;
  if char_length(btrim(coalesce(p_title, ''))) = 0 then raise exception 'Give the challenge a name.'; end if;
  if p_starts is null or p_ends is null or p_ends < p_starts then raise exception 'The challenge has to end on or after the day it starts.'; end if;
  if p_kind in ('target', 'club_total') and coalesce(p_target_m, 0) < 1000 then raise exception 'Set the metres to aim for.'; end if;
  if p_kind = 'squads' then
    if cardinality(v_squads) < 2 then raise exception 'Choose at least two squads.'; end if;
    if exists (select 1 from unnest(v_squads) s where not exists (select 1 from squads q where q.id = s and q.club_id = v_club)) then
      raise exception 'Choose squads from your club.';
    end if;
  else
    v_squads := '{}';
  end if;
  if v_id is null then
    insert into challenges (club_id, kind, title, target_m, squad_ids, starts_on, ends_on, created_by)
    values (v_club, p_kind, btrim(p_title), case when p_kind = 'squads' then null else p_target_m end, v_squads, p_starts, p_ends, auth.uid())
    returning id into v_id;
  else
    update challenges set kind = p_kind, title = btrim(p_title),
                          target_m = case when p_kind = 'squads' then null else p_target_m end,
                          squad_ids = v_squads, starts_on = p_starts, ends_on = p_ends
    where id = v_id and club_id = v_club;
    if not found then raise exception 'That challenge no longer exists.'; end if;
  end if;
  return v_id;
end $$;

create or replace function delete_challenge(p_id uuid)
returns void
language plpgsql security definer set search_path = public as $$
begin
  delete from challenges c where c.id = p_id and can_set_challenges(c.club_id);
end $$;

-- Every rower in the challenge's club with their metres on the leaderboards between its days, and
-- the squads they're in. Only for someone in that club.
create or replace function challenge_standings(p_challenge uuid)
returns table (user_id uuid, display_name text, metres int, squad_ids uuid[])
language plpgsql stable security definer set search_path = public as $$
declare
  v challenges;
begin
  select * into v from challenges where id = p_challenge;
  if v.id is null or v.club_id is distinct from (select p.club_id from profiles p where p.id = auth.uid()) then
    return;
  end if;
  return query
    select p.id, p.display_name,
           coalesce((select sum(d.ranked_erg_distance_m) from daily_totals d
                     where d.user_id = p.id and d.day >= v.starts_on and d.day <= v.ends_on), 0)::int,
           coalesce((select array_agg(m.squad_id) from squad_members m
                     join squads q on q.id = m.squad_id and q.club_id = v.club_id
                     where m.user_id = p.id), '{}')
    from profiles p
    where p.club_id = v.club_id and p.is_rower;
end $$;

-- MARK: - Erg events

create table if not exists erg_events (
  id          uuid primary key default gen_random_uuid(),
  club_id     uuid not null references clubs on delete cascade,
  title       text not null check (char_length(btrim(title)) between 1 and 60),
  distance_m  int check (distance_m between 100 and 100000),
  duration_ms int check (duration_ms between 30000 and 7200000),
  starts_at   timestamptz not null,
  ends_at     timestamptz not null,
  created_by  uuid,
  created_at  timestamptz not null default now(),
  constraint erg_events_one_piece check ((distance_m is null) <> (duration_ms is null)),
  constraint erg_events_window check (ends_at > starts_at and ends_at - starts_at <= interval '14 days')
);
create index if not exists erg_events_club_idx on erg_events (club_id, starts_at desc);
alter table erg_events enable row level security;
drop policy if exists read_own_club on erg_events;
create policy read_own_club on erg_events for select to authenticated
  using (club_id = (select p.club_id from profiles p where p.id = auth.uid()));

-- A post can count for one erg event.
alter table sessions add column if not exists erg_event_id uuid references erg_events on delete set null;
create index if not exists sessions_erg_event_idx on sessions (erg_event_id) where erg_event_id is not null;

create or replace function save_erg_event(
  p_id uuid, p_title text, p_distance_m int, p_duration_ms int, p_starts timestamptz, p_ends timestamptz
)
returns uuid
language plpgsql security definer set search_path = public as $$
declare
  v_club uuid;
  v_id uuid := p_id;
begin
  select club_id into v_club from profiles where id = auth.uid();
  if v_club is null or not can_set_challenges(v_club) then
    raise exception 'Only your club''s coaches, owner, co-owners and admins can set erg events.';
  end if;
  if char_length(btrim(coalesce(p_title, ''))) = 0 then raise exception 'Give the event a name.'; end if;
  if (p_distance_m is null) = (p_duration_ms is null) then raise exception 'Set the piece: a distance or a time.'; end if;
  if p_starts is null or p_ends is null or p_ends <= p_starts then raise exception 'The event has to end after it starts.'; end if;
  if v_id is null then
    insert into erg_events (club_id, title, distance_m, duration_ms, starts_at, ends_at, created_by)
    values (v_club, btrim(p_title), p_distance_m, p_duration_ms, p_starts, p_ends, auth.uid())
    returning id into v_id;
  else
    update erg_events set title = btrim(p_title), distance_m = p_distance_m, duration_ms = p_duration_ms,
                          starts_at = p_starts, ends_at = p_ends
    where id = v_id and club_id = v_club;
    if not found then raise exception 'That event no longer exists.'; end if;
  end if;
  return v_id;
end $$;

create or replace function delete_erg_event(p_id uuid)
returns void
language plpgsql security definer set search_path = public as $$
begin
  delete from erg_events e where e.id = p_id and can_set_challenges(e.club_id);
end $$;

-- The event's board: each rower in the club's best piece counted for it — posted from its start to
-- six hours after its end, the right distance exactly (a monitor stops on it) or the right time
-- within the finish-line tolerance tests use. Fastest first for a distance; furthest first for a
-- time. Only for someone in that club.
create or replace function erg_event_board(p_event uuid)
returns table (user_id uuid, display_name text, gender rower_gender, category rower_category,
               distance_m int, time_ms int, session_id uuid)
language plpgsql stable security definer set search_path = public as $$
declare
  e erg_events;
begin
  select * into e from erg_events where id = p_event;
  if e.id is null or e.club_id is distinct from (select p.club_id from profiles p where p.id = auth.uid()) then
    return;
  end if;
  return query
    select distinct on (s.user_id)
           s.user_id, p.display_name, p.gender, p.category, g.distance_m, g.time_ms, s.id
    from sessions s
    join profiles p on p.id = s.user_id and p.club_id = e.club_id and p.is_rower
    join lateral (
      select x.distance_m, x.time_ms from segments x
      where x.session_id = s.id
      order by x.is_lead desc, (x.label = 'main') desc, x.position
      limit 1
    ) g on true
    where s.erg_event_id = e.id
      -- Photographed pieces only, as for tests: a manual entry can't be checked.
      and s.photo_verified
      and s.posted_at >= e.starts_at and s.posted_at <= e.ends_at + interval '6 hours'
      and (
        (e.distance_m is not null and g.distance_m = e.distance_m)
        or (e.duration_ms is not null
            and abs(g.time_ms - e.duration_ms) <= greatest(least(2000, e.duration_ms / 20), e.duration_ms / 100))
      )
    order by s.user_id,
             case when e.distance_m is not null then g.time_ms else -g.distance_m end;
end $$;

-- MARK: - Access to the functions

revoke all on function can_set_challenges(uuid) from public, anon;
grant execute on function can_set_challenges(uuid) to authenticated;
revoke all on function save_challenge(uuid, text, text, int, uuid[], date, date) from public, anon;
grant execute on function save_challenge(uuid, text, text, int, uuid[], date, date) to authenticated;
revoke all on function delete_challenge(uuid) from public, anon;
grant execute on function delete_challenge(uuid) to authenticated;
revoke all on function challenge_standings(uuid) from public, anon;
grant execute on function challenge_standings(uuid) to authenticated;
revoke all on function save_erg_event(uuid, text, int, int, timestamptz, timestamptz) from public, anon;
grant execute on function save_erg_event(uuid, text, int, int, timestamptz, timestamptz) to authenticated;
revoke all on function delete_erg_event(uuid) from public, anon;
grant execute on function delete_erg_event(uuid) to authenticated;
revoke all on function erg_event_board(uuid) from public, anon;
grant execute on function erg_event_board(uuid) to authenticated;

commit;

-- The API sees the new tables, column and functions straight away.
notify pgrst, 'reload schema';


-- ################################################################################
-- docs/migrations/2026-10-18-season-wrapped.sql
-- ################################################################################
-- Season Wrapped (v2, user 2026-10-18; decision 92).
-- Run once in the Supabase SQL editor, staging first. Safe to run again. Works before or after
-- 2026-10-18-crew-tags.sql and 2026-10-18-challenges-and-erg-events.sql: the parts that read their
-- tables are left empty until they exist.
--
-- One rower's season between two days (a club term, or dates they choose), worked out for the
-- signed-in rower only:
--   totals and streaks — erg metres, sessions, time on the erg, days rowed, longest streak, biggest
--                        week, busiest month;
--   PBs and tests      — the personal bests set, the best 2k and how much it improved on the best before;
--   club and crew      — their place on their own group's metres in the club, who they trained with
--                        most (crew tags, either way round), personal-target challenges finished;
--   training mix       — time in each zone, and whether they row mornings, afternoons or evenings.

create or replace function season_wrapped(p_from date, p_to date)
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  v_me uuid := auth.uid();
  v_profile profiles;
  v_metres int;
  v_sessions int;
  v_days int;
  v_time bigint;
  v_streak int;
  v_week jsonb;
  v_month jsonb;
  v_pbs jsonb;
  v_best_2k bigint;
  v_best_2k_before bigint;
  v_place jsonb;
  v_mates jsonb := '[]'::jsonb;
  v_challenges jsonb := '[]'::jsonb;
  v_zones jsonb;
  v_times jsonb;
begin
  if v_me is null then raise exception 'Sign in first.'; end if;
  if p_from is null or p_to is null or p_to < p_from or p_to - p_from > 400 then
    raise exception 'Choose two dates up to a year apart.';
  end if;
  select * into v_profile from profiles where id = v_me;

  -- Totals and streaks.
  select coalesce(sum(d.erg_distance_m), 0), coalesce(sum(d.session_count), 0), count(*) filter (where d.session_count > 0)
    into v_metres, v_sessions, v_days
  from daily_totals d where d.user_id = v_me and d.day between p_from and p_to;

  select coalesce(sum(s.total_time_ms), 0) into v_time
  from sessions s where s.user_id = v_me and s.session_date between p_from and p_to;

  with rowed as (
    select d.day from daily_totals d where d.user_id = v_me and d.day between p_from and p_to and d.session_count > 0
  ), runs as (
    select r.day - (row_number() over (order by r.day))::int as run from rowed r
  )
  select coalesce(max(n), 0) into v_streak from (select count(*) as n from runs group by run) x;

  select jsonb_build_object('start', w.start, 'metres', w.metres) into v_week
  from (
    select date_trunc('week', d.day)::date as start, sum(d.erg_distance_m)::int as metres
    from daily_totals d where d.user_id = v_me and d.day between p_from and p_to
    group by 1 having sum(d.erg_distance_m) > 0 order by 2 desc, 1 limit 1
  ) w;

  select jsonb_build_object('start', m.start, 'metres', m.metres) into v_month
  from (
    select date_trunc('month', d.day)::date as start, sum(d.erg_distance_m)::int as metres
    from daily_totals d where d.user_id = v_me and d.day between p_from and p_to
    group by 1 having sum(d.erg_distance_m) > 0 order by 2 desc, 1 limit 1
  ) m;

  -- PBs and tests.
  select coalesce(jsonb_agg(jsonb_build_object('key', t.distance_key, 'distance_m', t.distance_m, 'time_ms', t.time_ms, 'day', s.session_date)
                            order by s.session_date), '[]'::jsonb)
    into v_pbs
  from sessions s join test_results t on t.session_id = s.id
  where s.user_id = v_me and s.is_new_pb and s.session_date between p_from and p_to;

  select min(t.time_ms) into v_best_2k
  from test_results t join sessions s on s.id = t.session_id
  where t.user_id = v_me and t.distance_key = '2k' and s.session_date between p_from and p_to;

  select min(t.time_ms) into v_best_2k_before
  from test_results t join sessions s on s.id = t.session_id
  where t.user_id = v_me and t.distance_key = '2k' and s.session_date < p_from;

  -- Their place in their own group's metres in the club (the group Rankings opens on).
  if v_profile.club_id is not null and v_profile.is_rower then
    with totals as (
      select p.id, p.created_at, coalesce(sum(d.ranked_erg_distance_m), 0)::int as metres
      from profiles p
      left join daily_totals d on d.user_id = p.id and d.day between p_from and p_to
      where p.club_id = v_profile.club_id and p.is_rower
        and (v_profile.gender is null or (p.gender = v_profile.gender and p.category = v_profile.category))
      group by p.id
    ), me as (select * from totals where id = v_me)
    select case when me.metres > 0 then jsonb_build_object(
             'place', (select count(*) from totals o where o.metres > 0
                       and (o.metres > me.metres or (o.metres = me.metres and (o.created_at, o.id) < (me.created_at, me.id)))) + 1,
             'of', (select count(*) from totals o where o.metres > 0),
             'group', case when v_profile.gender is null then 'rowers in your club'
                           else v_profile.category::text || ' ' || case v_profile.gender when 'M' then 'men' else 'women' end end)
           end
      into v_place
    from me;
  end if;

  -- Who they trained with most: people they tagged, and people who tagged them.
  if to_regclass('public.session_tags') is not null then
    execute $q$
      with pairs as (
        select t.user_id as other from session_tags t join sessions s on s.id = t.session_id
        where s.user_id = $1 and s.session_date between $2 and $3
        union all
        select s.user_id from session_tags t join sessions s on s.id = t.session_id
        where t.user_id = $1 and s.session_date between $2 and $3
      ), counted as (
        select other, count(*)::int as sessions from pairs group by other order by 2 desc limit 3
      )
      select coalesce(jsonb_agg(jsonb_build_object('user_id', c.other, 'name', p.display_name, 'sessions', c.sessions)
                                order by c.sessions desc, p.display_name), '[]'::jsonb)
      from counted c join profiles p on p.id = c.other
    $q$ into v_mates using v_me, p_from, p_to;
  end if;

  -- Personal-target challenges that ended in the season and that they reached.
  if to_regclass('public.challenges') is not null and v_profile.club_id is not null then
    execute $q$
      select coalesce(jsonb_agg(c.title order by c.ends_on), '[]'::jsonb)
      from challenges c
      where c.club_id = $4 and c.kind = 'target' and c.ends_on between $2 and $3
        and (select coalesce(sum(d.ranked_erg_distance_m), 0) from daily_totals d
             where d.user_id = $1 and d.day between c.starts_on and c.ends_on) >= c.target_m
    $q$ into v_challenges using v_me, p_from, p_to, v_profile.club_id;
  end if;

  -- Training mix.
  select coalesce(jsonb_agg(jsonb_build_object('zone', z.zone, 'time_ms', z.ms) order by z.ms desc), '[]'::jsonb)
    into v_zones
  from (
    select coalesce(nullif(s.zone, ''), 'Other') as zone, sum(s.total_time_ms)::bigint as ms
    from sessions s where s.user_id = v_me and s.session_date between p_from and p_to
    group by 1
  ) z;

  select jsonb_build_object(
           'morning', count(*) filter (where extract(hour from s.captured_at at time zone 'Europe/London') < 12),
           'afternoon', count(*) filter (where extract(hour from s.captured_at at time zone 'Europe/London') between 12 and 16),
           'evening', count(*) filter (where extract(hour from s.captured_at at time zone 'Europe/London') >= 17))
    into v_times
  from sessions s where s.user_id = v_me and s.session_date between p_from and p_to;

  return jsonb_build_object(
    'metres', v_metres, 'sessions', v_sessions, 'days', v_days, 'time_ms', v_time, 'longest_streak', v_streak,
    'biggest_week', v_week, 'busiest_month', v_month,
    'pbs', v_pbs, 'best_2k_ms', v_best_2k, 'best_2k_before_ms', v_best_2k_before,
    'club_place', v_place, 'trained_with', v_mates, 'challenges_done', v_challenges,
    'zones', v_zones, 'time_of_day', v_times
  );
end $$;

revoke all on function season_wrapped(date, date) from public, anon;
grant execute on function season_wrapped(date, date) to authenticated;

-- The API sees the new function straight away.
notify pgrst, 'reload schema';


-- ################################################################################
-- docs/migrations/2026-11-03-mutual-follow-posts.sql
-- ################################################################################
-- Friends: a follower sees your posts only when you follow them back (decision 95, user
-- 2026-11-03). Run once in the Supabase SQL editor, staging first. Safe to run again. One
-- transaction.
--
-- The rule (amends decision 33's): you can see a post if it's yours, or —
--   * neither of you has blocked the other, and
--   * the author's account is public, or you're their approved follower, and
--   * the post's own setting lets you in:
--       "following" (shown as Friends) → you follow each other, both accepted;
--       "club"                         → you're in the author's club;
--       "everyone"                     → either.
-- A one-way follower no longer sees Friends or Everyone posts. Clubmates are unchanged.
-- Not changed: profile stats, test results, rankings and the follows themselves.
--
-- may_notify (alerts) is the same rule for the person being told, so a PB or club alert never
-- points at a post they can't open.

begin;

create or replace function can_view_session(sid uuid)
returns boolean
language sql stable security definer set search_path = public as $$
  select coalesce((
    select s.user_id = auth.uid()
      or (
        not exists (
          select 1 from blocks b
          where (b.blocker_id = auth.uid() and b.blocked_id = s.user_id)
             or (b.blocker_id = s.user_id and b.blocked_id = auth.uid())
        )
        and (
          not author.is_private
          or exists (
            select 1 from follows f
            where f.follower_id = auth.uid() and f.followee_id = s.user_id and f.status = 'accepted'
          )
        )
        and (
          (s.visibility in ('following', 'everyone')
           and exists (
             select 1 from follows f
             where f.follower_id = auth.uid() and f.followee_id = s.user_id and f.status = 'accepted'
           )
           and exists (
             select 1 from follows f
             where f.follower_id = s.user_id and f.followee_id = auth.uid() and f.status = 'accepted'
           ))
          or (s.visibility in ('club', 'everyone')
              and author.club_id is not null
              and author.club_id = (select viewer.club_id from profiles viewer where viewer.id = auth.uid()))
        )
      )
    from sessions s
    join profiles author on author.id = s.user_id
    where s.id = sid
  ), false);
$$;

create or replace function may_notify(recipient uuid, actor uuid, sid uuid)
returns boolean
language sql stable security definer set search_path = public as $$
  select exists (
    select 1
    from sessions s
    join profiles author on author.id = s.user_id
    left join profiles viewer on viewer.id = recipient
    where s.id = sid
      and not exists (
        select 1 from blocks b
        where (b.blocker_id = recipient and b.blocked_id in (actor, s.user_id))
           or (b.blocked_id = recipient and b.blocker_id in (actor, s.user_id))
      )
      and (
        s.user_id = recipient
        or (
          (not author.is_private or exists (
            select 1 from follows f
            where f.follower_id = recipient and f.followee_id = s.user_id and f.status = 'accepted'))
          and (
            (s.visibility in ('following', 'everyone')
             and exists (
               select 1 from follows f
               where f.follower_id = recipient and f.followee_id = s.user_id and f.status = 'accepted')
             and exists (
               select 1 from follows f
               where f.follower_id = s.user_id and f.followee_id = recipient and f.status = 'accepted'))
            or (s.visibility in ('club', 'everyone')
                and author.club_id is not null and viewer.club_id = author.club_id)
          )
        )
      )
  );
$$;
revoke all on function may_notify(uuid, uuid, uuid) from public, anon, authenticated;

commit;


-- ################################################################################
-- docs/migrations/2026-11-05-coach-notepad.sql
-- ################################################################################
-- Coach notepad, phase NP1 (user, 2026-11-05; decision 96; docs/design/coach-notepad-build-plan.md).
-- Run once in the Supabase SQL editor, staging first, after 2026-11-03-mutual-follow-posts.sql.
-- Safe to run again.
--
-- What it adds:
--   1. coach_notepads: one page per set workout — its text and table blocks, its Notes, and the
--      order the coach put the rowers in (erg order).
--   2. coach_notepad_scores: a score the coach typed (or, from NP2, scanned) for one rower's rep.
--   3. save_notepad, save_notepad_score, delete_notepad_score: the only way to write either table.
--
-- Coach-only: every coach in the workout's club reads and edits every page (user, 2026-11-05).
-- Rowers can't read either table. Nothing else in the database reads them, so nothing written here
-- reaches volume, pieces, PBs, predictions, streaks, Wrapped, challenges or any leaderboard.

begin;

-- MARK: - 1. Pages

create table if not exists coach_notepads (
  workout_id  uuid primary key references coach_workouts on delete cascade,
  club_id     uuid not null references clubs on delete cascade,
  -- [{ "id": "<uuid>", "kind": "text", "text": "…" }
  --  { "id": "<uuid>", "kind": "table", "title": "…", "cells": [["Rower", "Technique"], ["", ""]] }]
  -- The Scores table isn't a block: every page has it, above the blocks.
  blocks      jsonb not null default '[]'::jsonb,
  notes       text not null default '',
  -- The rowers in the order the coach put them (erg order); anyone not listed follows, by name.
  rower_order uuid[] not null default '{}',
  updated_by  uuid references profiles on delete set null,
  updated_at  timestamptz not null default now()
);

alter table coach_notepads drop constraint if exists coach_notepads_blocks_array;
alter table coach_notepads add constraint coach_notepads_blocks_array
  check (jsonb_typeof(blocks) = 'array' and jsonb_array_length(blocks) <= 30);
alter table coach_notepads drop constraint if exists coach_notepads_notes_length;
alter table coach_notepads add constraint coach_notepads_notes_length check (char_length(notes) <= 10000);

alter table coach_notepads enable row level security;
drop policy if exists coaches_read on coach_notepads;
create policy coaches_read on coach_notepads for select to authenticated
  using (is_club_coach(club_id));

-- MARK: - 2. Scores

create table if not exists coach_notepad_scores (
  workout_id    uuid not null references coach_workouts on delete cascade,
  user_id       uuid not null references profiles on delete cascade,
  -- The rep, counting every rep of every piece from 0 (3 × 2,000m has reps 0, 1 and 2).
  piece_index   int not null,
  club_id       uuid not null references clubs on delete cascade,
  split_ms      int,
  -- What the coach typed, when it wasn't the split: the time off the monitor (a distance piece)
  -- or the metres (a time piece). The split is always worked out and stored.
  time_ms       int,
  distance_m    int,
  rate          smallint,
  sat_out       boolean not null default false,
  -- A test's 500m splits, when they were scanned (NP3).
  splits_500_ms int[],
  source        text not null default 'typed',
  updated_by    uuid references profiles on delete set null,
  updated_at    timestamptz not null default now(),
  primary key (workout_id, user_id, piece_index)
);

alter table coach_notepad_scores drop constraint if exists coach_notepad_scores_valid;
alter table coach_notepad_scores add constraint coach_notepad_scores_valid check (
  piece_index between 0 and 199
  and source in ('typed', 'scanned')
  and (sat_out or split_ms is not null)
  and (split_ms is null or split_ms between 30000 and 600000)
  and (time_ms is null or time_ms between 1000 and 36000000)
  and (distance_m is null or distance_m between 1 and 100000)
  and (rate is null or rate between 10 and 70)
);

alter table coach_notepad_scores enable row level security;
drop policy if exists coaches_read on coach_notepad_scores;
create policy coaches_read on coach_notepad_scores for select to authenticated
  using (is_club_coach(club_id));

-- MARK: - 3. Writing

-- The workout's club, once the caller is shown to coach it. Internal.
create or replace function notepad_club(p_workout uuid)
returns uuid
language plpgsql stable security definer set search_path = public as $$
declare
  v_club uuid;
begin
  select club_id into v_club from coach_workouts where id = p_workout;
  if v_club is null then raise exception 'That workout has gone.'; end if;
  if not is_club_coach(v_club) then raise exception 'Only your club''s coaches can use the notepad.'; end if;
  return v_club;
end $$;

-- Saves a page's blocks, Notes and rower order (made on its first save).
create or replace function save_notepad(p_workout uuid, p_blocks jsonb, p_notes text, p_rower_order uuid[])
returns void
language plpgsql security definer set search_path = public as $$
declare
  v_club uuid := notepad_club(p_workout);
  v_block jsonb;
  v_row jsonb;
begin
  if p_blocks is null or jsonb_typeof(p_blocks) <> 'array' then raise exception 'The page couldn''t be read.'; end if;
  if jsonb_array_length(p_blocks) > 30 then raise exception 'A page holds up to 30 text boxes and tables.'; end if;
  for v_block in select * from jsonb_array_elements(p_blocks) loop
    if v_block->>'kind' = 'text' then
      if char_length(coalesce(v_block->>'text', '')) > 4000 then raise exception 'A text box holds up to 4,000 characters.'; end if;
    elsif v_block->>'kind' = 'table' then
      if char_length(coalesce(v_block->>'title', '')) > 80 then raise exception 'A table''s name is up to 80 characters.'; end if;
      if jsonb_typeof(v_block->'cells') <> 'array' or jsonb_array_length(v_block->'cells') > 51 then
        raise exception 'A table holds up to 50 rows.';
      end if;
      for v_row in select * from jsonb_array_elements(v_block->'cells') loop
        if jsonb_typeof(v_row) <> 'array' or jsonb_array_length(v_row) > 5 then raise exception 'A table holds up to 5 columns.'; end if;
        if exists (select 1 from jsonb_array_elements_text(v_row) c where char_length(c) > 200) then
          raise exception 'A table box holds up to 200 characters.';
        end if;
      end loop;
    else
      raise exception 'The page couldn''t be read.';
    end if;
  end loop;

  insert into coach_notepads (workout_id, club_id, blocks, notes, rower_order, updated_by, updated_at)
  values (p_workout, v_club, p_blocks, coalesce(p_notes, ''), coalesce(p_rower_order, '{}'), auth.uid(), now())
  on conflict (workout_id) do update
    set blocks = excluded.blocks, notes = excluded.notes, rower_order = excluded.rower_order,
        updated_by = excluded.updated_by, updated_at = excluded.updated_at;
end $$;

-- Saves one rower's score for one rep: a split (with what was typed to get it), or sat out.
create or replace function save_notepad_score(
  p_workout uuid, p_user uuid, p_piece int, p_split_ms int, p_time_ms int, p_distance_m int,
  p_rate int, p_sat_out boolean, p_source text
)
returns void
language plpgsql security definer set search_path = public as $$
declare
  v_club uuid := notepad_club(p_workout);
  v_reps int;
begin
  if not exists (select 1 from profiles where id = p_user and club_id = v_club) then
    raise exception 'That rower isn''t in your club.';
  end if;
  select greatest(1, coalesce(sum(greatest(1, coalesce((p->>'reps')::int, 1))), 0))::int into v_reps
  from coach_workouts w, jsonb_array_elements(w.pieces) p where w.id = p_workout;
  if p_piece is null or p_piece < 0 or p_piece >= coalesce(v_reps, 1) then raise exception 'That piece isn''t in this workout.'; end if;
  if not coalesce(p_sat_out, false) and (p_split_ms is null or p_split_ms not between 30000 and 600000) then
    raise exception 'Type a split between 0:30.0 and 10:00.0, or mark them as sat out.';
  end if;

  insert into coach_notepad_scores (workout_id, user_id, piece_index, club_id, split_ms, time_ms, distance_m,
                                    rate, sat_out, source, updated_by, updated_at)
  values (p_workout, p_user, p_piece, v_club,
          case when coalesce(p_sat_out, false) then null else p_split_ms end,
          case when coalesce(p_sat_out, false) then null else p_time_ms end,
          case when coalesce(p_sat_out, false) then null else p_distance_m end,
          case when coalesce(p_sat_out, false) then null else p_rate end,
          coalesce(p_sat_out, false), coalesce(p_source, 'typed'), auth.uid(), now())
  on conflict (workout_id, user_id, piece_index) do update
    set split_ms = excluded.split_ms, time_ms = excluded.time_ms, distance_m = excluded.distance_m,
        rate = excluded.rate, sat_out = excluded.sat_out, source = excluded.source,
        updated_by = excluded.updated_by, updated_at = excluded.updated_at;
end $$;

-- Takes one score off the page (the box goes back to the rower's own post, or empty).
create or replace function delete_notepad_score(p_workout uuid, p_user uuid, p_piece int)
returns void
language plpgsql security definer set search_path = public as $$
begin
  perform notepad_club(p_workout);
  delete from coach_notepad_scores where workout_id = p_workout and user_id = p_user and piece_index = p_piece;
end $$;

revoke all on function notepad_club(uuid) from public;
grant execute on function save_notepad(uuid, jsonb, text, uuid[]) to authenticated;
grant execute on function save_notepad_score(uuid, uuid, int, int, int, int, int, boolean, text) to authenticated;
grant execute on function delete_notepad_score(uuid, uuid, int) to authenticated;

commit;


-- ################################################################################
-- docs/migrations/2026-11-05-coach-notepad-np3.sql
-- ################################################################################
-- Coach notepad, phase NP3 (user, 2026-11-05; decision 96; docs/design/coach-notepad-build-plan.md).
-- Run once in the Supabase SQL editor, after 2026-11-05-coach-notepad.sql. Safe to run again.
-- Run it on every project a build points at before that build is used: posting writes the new
-- segments column, and the notepad reads it.
--
-- What it does:
--   1. segments.splits_500_ms: the split of every row the monitor shows under a continuous piece
--      (a 2k's four 500m splits), kept when a rower posts, so a coach's test notepad can show them.
--   2. save_notepad_score takes the 500m splits too (a test scanned off the monitor).
--   3. Fix: a workout set with only a title ("4 x 500m", no pieces) takes scores for every rep the
--      app reads from the title. The server used to count reps from the pieces only, so it refused
--      every rep after the first on such a workout.

begin;

-- MARK: - 1. Splits on posted segments

alter table segments add column if not exists splits_500_ms int[];

alter table segments drop constraint if exists segments_splits_500_ms_valid;
alter table segments add constraint segments_splits_500_ms_valid check (
  splits_500_ms is null
  or (cardinality(splits_500_ms) between 1 and 100
      and 30000 <= all (splits_500_ms) and 600000 >= all (splits_500_ms))
);

-- MARK: - 2 and 3. Saving a score

alter table coach_notepad_scores drop constraint if exists coach_notepad_scores_splits_valid;
alter table coach_notepad_scores add constraint coach_notepad_scores_splits_valid check (
  splits_500_ms is null
  or (cardinality(splits_500_ms) between 1 and 100
      and 30000 <= all (splits_500_ms) and 600000 >= all (splits_500_ms))
);

-- The old nine-argument version goes; the new one has the splits as a tenth.
drop function if exists save_notepad_score(uuid, uuid, int, int, int, int, int, boolean, text);

create or replace function save_notepad_score(
  p_workout uuid, p_user uuid, p_piece int, p_split_ms int, p_time_ms int, p_distance_m int,
  p_rate int, p_sat_out boolean, p_source text, p_splits_500_ms int[] default null
)
returns void
language plpgsql security definer set search_path = public as $$
declare
  v_club uuid := notepad_club(p_workout);
  v_has_pieces boolean;
  v_reps int;
begin
  if not exists (select 1 from profiles where id = p_user and club_id = v_club) then
    raise exception 'That rower isn''t in your club.';
  end if;
  select coalesce(jsonb_array_length(w.pieces), 0) > 0 into v_has_pieces from coach_workouts w where w.id = p_workout;
  if coalesce(v_has_pieces, false) then
    select greatest(1, coalesce(sum(greatest(1, coalesce((p->>'reps')::int, 1))), 0))::int into v_reps
    from coach_workouts w, jsonb_array_elements(w.pieces) p where w.id = p_workout;
  else
    -- No pieces: the app takes the reps from the title. The table's own limit (200) still holds.
    v_reps := 200;
  end if;
  if p_piece is null or p_piece < 0 or p_piece >= coalesce(v_reps, 1) then raise exception 'That piece isn''t in this workout.'; end if;
  if not coalesce(p_sat_out, false) and (p_split_ms is null or p_split_ms not between 30000 and 600000) then
    raise exception 'Type a split between 0:30.0 and 10:00.0, or mark them as sat out.';
  end if;

  insert into coach_notepad_scores (workout_id, user_id, piece_index, club_id, split_ms, time_ms, distance_m,
                                    rate, sat_out, splits_500_ms, source, updated_by, updated_at)
  values (p_workout, p_user, p_piece, v_club,
          case when coalesce(p_sat_out, false) then null else p_split_ms end,
          case when coalesce(p_sat_out, false) then null else p_time_ms end,
          case when coalesce(p_sat_out, false) then null else p_distance_m end,
          case when coalesce(p_sat_out, false) then null else p_rate end,
          coalesce(p_sat_out, false),
          case when coalesce(p_sat_out, false) then null else p_splits_500_ms end,
          coalesce(p_source, 'typed'), auth.uid(), now())
  on conflict (workout_id, user_id, piece_index) do update
    set split_ms = excluded.split_ms, time_ms = excluded.time_ms, distance_m = excluded.distance_m,
        rate = excluded.rate, sat_out = excluded.sat_out, splits_500_ms = excluded.splits_500_ms,
        source = excluded.source, updated_by = excluded.updated_by, updated_at = excluded.updated_at;
end $$;

grant execute on function save_notepad_score(uuid, uuid, int, int, int, int, int, boolean, text, int[]) to authenticated;

commit;


-- ################################################################################
-- docs/migrations/2026-11-05-coach-notepad-np4.sql
-- ################################################################################
-- Coach notepad, phase NP4 (user, 2026-11-05; decision 96; docs/design/coach-notepad-build-plan.md).
-- Run once in the Supabase SQL editor, after 2026-11-05-coach-notepad-np3.sql. Safe to run again.
--
-- What it adds: my_notepad_scores(p_since), the one way a rower sees anything from a notepad — the
-- scores the club's coaches noted for *them*, for their Feed card (RowerCoachScores). It never
-- returns another rower's scores, or any page's text, tables or Notes. Rowers still can't read the
-- notepad tables themselves.

begin;

create or replace function my_notepad_scores(p_since date)
returns table (
  workout_id uuid, title text, workout_date date, pieces jsonb, test_key text,
  coach_name text, club_name text,
  -- Where the coach put the rower in erg order (1 = first erg); null when not placed.
  erg int,
  piece_index int, split_ms int, sat_out boolean,
  -- The rower's own posted average for the workout, when they posted it with "Link this session".
  posted_avg_split_ms int
)
language sql stable security definer set search_path = public as $$
  select w.id, w.title, w.workout_date, w.pieces, w.test_key,
         coach.display_name, club.name,
         array_position(page.rower_order, auth.uid()),
         s.piece_index, s.split_ms, s.sat_out,
         (select own.avg_split_ms from sessions own
          where own.workout_id = w.id and own.user_id = auth.uid()
          order by own.posted_at desc limit 1)
  from coach_notepad_scores s
  join coach_workouts w on w.id = s.workout_id
  left join coach_notepads page on page.workout_id = w.id
  left join profiles coach on coach.id = w.created_by
  left join clubs club on club.id = w.club_id
  where s.user_id = auth.uid()
    -- Only while they're still in that club.
    and w.club_id = (select me.club_id from profiles me where me.id = auth.uid())
    and w.workout_date >= p_since
  order by w.workout_date desc, s.piece_index;
$$;

revoke all on function my_notepad_scores(date) from public;
grant execute on function my_notepad_scores(date) to authenticated;

commit;


-- ################################################################################
-- docs/migrations/2026-11-05-edit-workout.sql
-- ################################################################################
-- Editing a set workout (user, 2026-11-05: "there is no way to edit a workout"). Run once in the
-- Supabase SQL editor, on every project a build points at. Safe to run again.
--
-- update_workout: the club's coaches change a workout's title, day, time, notes, zone, test, pieces
-- and who it's for, with the same checks as create_workout. Rowers aren't alerted again. Sessions
-- already linked to it stay linked; a notepad keeps its page and scores.

begin;

create or replace function update_workout(
  p_workout uuid, p_title text, p_date date, p_start_time time, p_description text, p_zone text,
  p_test_key text, p_pieces jsonb, p_audience text, p_squads uuid[], p_rowers uuid[]
)
returns void
language plpgsql security definer set search_path = public as $$
declare
  v_club uuid;
begin
  select club_id into v_club from coach_workouts where id = p_workout;
  if v_club is null then raise exception 'That workout isn''t there any more.'; end if;
  if not is_club_coach(v_club) then raise exception 'Only your club''s coaches can change workouts.'; end if;
  if coalesce(char_length(btrim(p_title)), 0) = 0 then raise exception 'Give the workout a title.'; end if;
  if p_audience not in ('club', 'squads', 'rowers') then raise exception 'Choose who the workout is for.'; end if;
  if jsonb_typeof(coalesce(p_pieces, '[]'::jsonb)) <> 'array' then raise exception 'Pieces must be a list.'; end if;
  if p_test_key is not null
     and p_test_key not in ('500m', '1k', '2k', '5k', '6k', '10k', '4min', '30min', '60min')
     and not exists (select 1 from club_tests ct where ct.club_id = v_club and 'club:' || ct.id::text = p_test_key) then
    raise exception 'That test isn''t one of your club''s tests.';
  end if;

  update coach_workouts
     set title = btrim(p_title), workout_date = p_date, start_time = p_start_time,
         description = nullif(btrim(coalesce(p_description, '')), ''), zone = p_zone,
         test_key = p_test_key, pieces = coalesce(p_pieces, '[]'::jsonb), audience = p_audience
   where id = p_workout;

  delete from coach_workout_targets where workout_id = p_workout;
  if p_audience = 'squads' then
    insert into coach_workout_targets (workout_id, squad_id)
      select p_workout, s.id from squads s where s.id = any(coalesce(p_squads, '{}')) and s.club_id = v_club;
    if not found then raise exception 'Choose at least one squad.'; end if;
  elsif p_audience = 'rowers' then
    insert into coach_workout_targets (workout_id, user_id)
      select p_workout, p.id from profiles p
      where p.id = any(coalesce(p_rowers, '{}')) and p.club_id = v_club and p.is_rower;
    if not found then raise exception 'Choose at least one rower.'; end if;
  end if;
end $$;

revoke all on function update_workout(uuid, text, date, time, text, text, text, jsonb, text, uuid[], uuid[]) from public;
grant execute on function update_workout(uuid, text, date, time, text, text, text, jsonb, text, uuid[], uuid[]) to authenticated;

commit;


-- ################################################################################
-- docs/migrations/2026-11-05-clubs-open-and-verified.sql
-- ################################################################################
-- Clubs anyone can start, unique names, renaming, and verified clubs (decision 98).
-- Run once in the Supabase SQL editor, Staging first. Safe to run again.
--
-- Run docs/migrations/2026-11-05-delete-all-clubs.sql FIRST if you're clearing the clubs out:
-- the stricter name index below can't be built while two clubs share a name that differs only by
-- spacing ("Tyne  RC" and "Tyne RC").
--
-- What it does:
--   * Club names are unique ignoring capitals and extra spaces ("Tyne RC", "tyne rc" and
--     " Tyne  RC " are one name), enforced by a unique index, and stored tidied.
--   * create_club / update_club tidy the name and say clearly when it's taken.
--   * rename_club: the owner (and co-owners, who can already edit the club) change just the name.
--   * club_name_is_free: the app checks a name as it's typed.
--   * Verified clubs: clubs.is_verified, set only by you in the SQL editor
--     (approve_club_verification). An owner applies from the app (apply_for_club_verification);
--     the application waits in club_verification_requests.

-- MARK: - Names

-- The one form two names are compared in: lower case, trimmed, runs of spaces made one.
create or replace function club_name_key(p_name text)
returns text
language sql immutable as $$
  select lower(regexp_replace(btrim(coalesce(p_name, '')), '\s+', ' ', 'g'));
$$;

drop index if exists clubs_name_unique;
create unique index clubs_name_unique on clubs (club_name_key(name));

-- Names are stored tidied (trimmed, single spaces). NOT VALID: checked for every new or changed
-- name, without failing on an older untidy one.
alter table clubs drop constraint if exists clubs_name_tidy;
alter table clubs add constraint clubs_name_tidy
  check (name = regexp_replace(btrim(name), '\s+', ' ', 'g')) not valid;

-- True when no other club has this name (ignoring capitals and spaces). `p_except` is the
-- caller's own club when renaming, so keeping its own name, or changing its capitals, is fine.
create or replace function club_name_is_free(p_name text, p_except uuid default null)
returns boolean
language sql stable security definer set search_path = public as $$
  select not exists (
    select 1 from clubs
    where club_name_key(name) = club_name_key(p_name)
      and (p_except is null or id <> p_except)
  );
$$;

-- MARK: - Verified clubs

alter table clubs add column if not exists is_verified boolean not null default false;
alter table clubs add column if not exists verified_at timestamptz;

-- One application per club: applying again after a decline replaces it.
create table if not exists club_verification_requests (
  club_id      uuid primary key references clubs on delete cascade,
  requested_by uuid references profiles on delete set null,
  message      text check (message is null or char_length(message) <= 500),
  status       text not null default 'pending' check (status in ('pending', 'approved', 'declined')),
  created_at   timestamptz not null default now(),
  decided_at   timestamptz
);
alter table club_verification_requests enable row level security;
-- The club's owner and co-owners can see where its application stands. Nobody writes the
-- table directly: applying goes through apply_for_club_verification, deciding through you.
drop policy if exists read_own_club on club_verification_requests;
create policy read_own_club on club_verification_requests
  for select to authenticated using (is_club_manager(club_id, 'co_owner'));

-- MARK: - Creating, editing and renaming

create or replace function create_club(p_name text, p_description text, p_location text, p_policy club_join_policy, p_focus text)
returns uuid
language plpgsql security definer set search_path = public as $$
declare
  v_club uuid;
  v_name text := regexp_replace(btrim(coalesce(p_name, '')), '\s+', ' ', 'g');
begin
  if auth.uid() is null then raise exception 'Not signed in'; end if;
  if v_name = '' then raise exception 'Give your club a name.'; end if;
  perform club_assert_not_owner();
  if not club_name_is_free(v_name) then
    raise exception 'There''s already a club called %. Club names have to be different (capitals don''t count), so choose another name.', v_name;
  end if;
  begin
    insert into clubs (name, description, location, join_policy, focus)
    values (v_name, nullif(trim(p_description), ''), nullif(trim(p_location), ''), p_policy, p_focus)
    returning id into v_club;
  exception when unique_violation then
    raise exception 'There''s already a club called %. Club names have to be different (capitals don''t count), so choose another name.', v_name;
  end;
  perform club_set_membership(auth.uid(), v_club, 'owner');
  return v_club;
end $$;

create or replace function update_club(p_name text, p_description text, p_location text, p_policy club_join_policy, p_focus text)
returns void
language plpgsql security definer set search_path = public as $$
declare
  v_club uuid;
  v_name text := regexp_replace(btrim(coalesce(p_name, '')), '\s+', ' ', 'g');
begin
  select club_id into v_club from profiles where id = auth.uid();
  if v_club is null or not is_club_manager(v_club, 'co_owner') then
    raise exception 'Only the owner and co-owners can edit the club.';
  end if;
  if v_name = '' then raise exception 'Give your club a name.'; end if;
  if not club_name_is_free(v_name, v_club) then
    raise exception 'There''s already a club called %. Choose another name.', v_name;
  end if;
  begin
    update clubs
    set name = v_name, description = nullif(trim(p_description), ''),
        location = nullif(trim(p_location), ''), join_policy = p_policy, focus = p_focus
    where id = v_club;
  exception when unique_violation then
    raise exception 'There''s already a club called %. Choose another name.', v_name;
  end;
end $$;

-- Settings → Your club → Club name. Same rule as editing the club.
create or replace function rename_club(p_name text)
returns void
language plpgsql security definer set search_path = public as $$
declare
  v_club uuid;
  v_name text := regexp_replace(btrim(coalesce(p_name, '')), '\s+', ' ', 'g');
begin
  select club_id into v_club from profiles where id = auth.uid();
  if v_club is null or not is_club_manager(v_club, 'co_owner') then
    raise exception 'Only the owner and co-owners can rename the club.';
  end if;
  if v_name = '' then raise exception 'Give your club a name.'; end if;
  if char_length(v_name) > 60 then raise exception 'Club names can be up to 60 characters.'; end if;
  if not club_name_is_free(v_name, v_club) then
    raise exception 'There''s already a club called %. Choose another name.', v_name;
  end if;
  begin
    update clubs set name = v_name where id = v_club;
  exception when unique_violation then
    raise exception 'There''s already a club called %. Choose another name.', v_name;
  end;
end $$;

-- MARK: - Applying for verification

-- The owner asks for the verified tag. Returns 'pending'.
create or replace function apply_for_club_verification(p_message text)
returns text
language plpgsql security definer set search_path = public as $$
declare
  v_club uuid;
  v_status text;
begin
  select club_id into v_club from profiles where id = auth.uid() and club_role = 'owner';
  if v_club is null then raise exception 'Only the club''s owner can apply for verification.'; end if;
  if exists (select 1 from clubs where id = v_club and is_verified) then
    raise exception 'Your club is already verified.';
  end if;
  select status into v_status from club_verification_requests where club_id = v_club;
  if v_status = 'pending' then
    raise exception 'Your application is already waiting to be looked at.';
  end if;
  insert into club_verification_requests (club_id, requested_by, message, status, created_at, decided_at)
  values (v_club, auth.uid(), nullif(left(btrim(coalesce(p_message, '')), 500), ''), 'pending', now(), null)
  on conflict (club_id) do update
    set requested_by = excluded.requested_by, message = excluded.message,
        status = 'pending', created_at = now(), decided_at = null;
  return 'pending';
end $$;

-- Where the caller's club stands: 'verified', 'pending', 'declined' or 'none'.
create or replace function club_verification_status()
returns text
language sql stable security definer set search_path = public as $$
  select case
    when c.is_verified then 'verified'
    else coalesce((select r.status from club_verification_requests r where r.club_id = c.id), 'none')
  end
  from profiles p join clubs c on c.id = p.club_id
  where p.id = auth.uid();
$$;

-- MARK: - Deciding (you, in the SQL editor only)

-- select approve_club_verification('<club id>');
create or replace function approve_club_verification(p_club uuid)
returns void
language plpgsql security definer set search_path = public as $$
begin
  update clubs set is_verified = true, verified_at = now() where id = p_club;
  if not found then raise exception 'No club has that id.'; end if;
  insert into club_verification_requests (club_id, status, decided_at)
  values (p_club, 'approved', now())
  on conflict (club_id) do update set status = 'approved', decided_at = now();
end $$;

-- select decline_club_verification('<club id>');  The owner can apply again.
create or replace function decline_club_verification(p_club uuid)
returns void
language plpgsql security definer set search_path = public as $$
begin
  update club_verification_requests set status = 'declined', decided_at = now() where club_id = p_club;
  if not found then raise exception 'That club hasn''t applied.'; end if;
end $$;

-- select remove_club_verification('<club id>');  Takes the tag away again.
create or replace function remove_club_verification(p_club uuid)
returns void
language plpgsql security definer set search_path = public as $$
begin
  update clubs set is_verified = false, verified_at = null where id = p_club;
  if not found then raise exception 'No club has that id.'; end if;
end $$;

-- MARK: - Who can call what

do $$
declare
  f text;
begin
  foreach f in array array[
    'create_club(text, text, text, club_join_policy, text)',
    'update_club(text, text, text, club_join_policy, text)',
    'rename_club(text)', 'club_name_is_free(text, uuid)',
    'apply_for_club_verification(text)', 'club_verification_status()'
  ] loop
    execute format('revoke all on function %s from public, anon', f);
    execute format('grant execute on function %s to authenticated', f);
  end loop;
  -- Deciding is yours alone: nobody signed in to the app can call these.
  foreach f in array array[
    'approve_club_verification(uuid)', 'decline_club_verification(uuid)', 'remove_club_verification(uuid)'
  ] loop
    execute format('revoke all on function %s from public, anon, authenticated', f);
  end loop;
end $$;

-- Ask PostgREST to pick up the new column and functions straight away.
notify pgrst, 'reload schema';


-- ################################################################################
-- docs/migrations/2026-11-13-automatic-leaderboards.sql
-- ################################################################################
-- Automatic leaderboards (decision 104, user 2026-11-13). Run once in the Supabase SQL editor,
-- staging first, BEFORE installing the build that needs it (posting writes the new segment columns).
-- Safe to run again: the back-fill skips any result a session already has.
--
-- What it does:
--   1. segments.is_interval, rep_times_ms and rep_distances_m: an interval workout, and each of its
--      reps as read off the monitor (and any next screens joined onto it), so every rep can rank.
--   2. ranking_tests(club): the nine standard tests plus a club's own, with their targets.
--   3. backfill_test_results(): ranks every photographed post made before this by the app's rules
--      (Rowing Pals/Core/Services/AutoRanking.swift): each Main or Extra piece, or interval rep, at
--      a test's distance or time puts the session's best for that test on its leaderboard, whatever
--      its rate, zone or Session type. Warm-ups and cool-downs never rank, nor does an interval
--      workout's total. Results are dated when the session was rowed, and a result that beat every
--      earlier one for its test makes the post a new PB (no alerts are sent for old posts).
--
-- Limits of the back-fill, said plainly:
--   * Posts from before this build kept no rep times, so an old interval session's reps can't be
--     ranked (its total isn't either). Its photos are still in Storage; re-reading them needs the app.
--   * Before 5 Nov an interval workout was only marked when its title gave a rep distance
--     ("8x500m"). An old timed-rep workout (3 x 10:00) can't be told from one continuous piece, so
--     its total could rank (a 3 x 10:00 as a 30min). Delete that result from the post if it shows.

begin;

-- MARK: - 1. Reps on posted pieces

alter table segments add column if not exists is_interval boolean not null default false;
alter table segments add column if not exists rep_times_ms int[];
alter table segments add column if not exists rep_distances_m int[];

alter table segments drop constraint if exists segments_reps_valid;
alter table segments add constraint segments_reps_valid check (
  (rep_times_ms is null and rep_distances_m is null)
  or (cardinality(rep_times_ms) = cardinality(rep_distances_m)
      and cardinality(rep_times_ms) between 1 and 100
      and 0 < all (rep_times_ms) and 0 < all (rep_distances_m))
);

-- Older interval posts: the ones whose title gave a rep distance.
update segments set is_interval = true where rep_distance_m is not null and not is_interval;

-- MARK: - 2. The tests a piece can rank on

create or replace function ranking_tests(p_club uuid)
returns table (key text, distance_m int, duration_ms int)
language sql stable set search_path = public as $$
  select v.key, v.distance_m, v.duration_ms
  from (values
    ('500m', 500, null::int), ('1k', 1000, null), ('2k', 2000, null), ('5k', 5000, null),
    ('6k', 6000, null), ('10k', 10000, null),
    ('4min', null, 240000), ('30min', null, 1800000), ('60min', null, 3600000)
  ) as v (key, distance_m, duration_ms)
  union all
  select 'club:' || c.id::text, c.distance_m, c.duration_ms
  from club_tests c
  where p_club is not null and c.club_id = p_club
$$;

-- MARK: - 3. Ranking posts made before automatic leaderboards

create or replace function backfill_test_results()
returns table (sessions_ranked int, results_added int, new_pbs int)
language plpgsql security definer set search_path = public as $$
declare
  s record;
  p profiles%rowtype;
  r record;
  v_sessions int := 0;
  v_results int := 0;
  v_pbs int := 0;
  v_added boolean;
  v_pb boolean;
  v_earlier_count int;
  v_earlier_max_m int;
  v_earlier_min_ms bigint;
begin
  for s in
    select * from sessions
    where photo_verified and coalesce(is_ranked, false) and type = 'erg'
    order by captured_at, posted_at
  loop
    select * into p from profiles where id = s.user_id;
    if not found or p.gender is null or p.category is null then continue; end if;
    v_added := false;
    v_pb := false;

    for r in
      with efforts as (
        -- A whole piece, when it isn't an interval workout.
        select g.id as segment_id, g.distance_m, g.time_ms::bigint as time_ms
        from segments g
        where g.session_id = s.id and g.label in ('main', 'extra')
          and g.monitor_photo_path is not null and not g.is_interval
        union all
        -- Each rep of an interval workout.
        select g.id, rep.d, rep.t::bigint
        from segments g
        cross join lateral unnest(g.rep_distances_m, g.rep_times_ms) as rep (d, t)
        where g.session_id = s.id and g.label in ('main', 'extra')
          and g.monitor_photo_path is not null and g.is_interval
      ),
      matched as (
        select t.key, (t.duration_ms is not null) as by_time, e.segment_id, e.distance_m, e.time_ms
        from efforts e
        join ranking_tests(p.club_id) t
          on (t.distance_m is not null and e.distance_m = t.distance_m)
          or (t.duration_ms is not null
              and abs(e.time_ms - t.duration_ms)
                  <= greatest(least(2000, t.duration_ms / 20), t.duration_ms / 100))
        where e.distance_m > 0 and e.time_ms > 0
      )
      -- The session's best for each test: furthest for a timed test, fastest otherwise.
      select distinct on (key) key, by_time, segment_id, distance_m, time_ms
      from matched
      order by key, case when by_time then -distance_m::bigint else time_ms end
    loop
      if exists (select 1 from test_results where session_id = s.id and distance_key = r.key) then
        continue;
      end if;

      select count(*), max(tr.distance_m), min(tr.time_ms)
      into v_earlier_count, v_earlier_max_m, v_earlier_min_ms
      from test_results tr
      join sessions ps on ps.id = tr.session_id
      where tr.user_id = s.user_id and tr.distance_key = r.key and ps.captured_at < s.captured_at;

      if v_earlier_count = 0
         or (r.by_time and r.distance_m > v_earlier_max_m)
         or (not r.by_time and r.time_ms < v_earlier_min_ms) then
        v_pb := true;
      end if;

      insert into test_results (
        user_id, session_id, segment_id, distance_key, distance_m, time_ms, split_ms,
        gender_at_time, category_at_time, set_at
      ) values (
        s.user_id, s.id, r.segment_id, r.key, r.distance_m, r.time_ms,
        round(r.time_ms / (r.distance_m / 500.0))::int,
        p.gender, p.category, s.captured_at
      );
      v_results := v_results + 1;
      v_added := true;
    end loop;

    if v_added then v_sessions := v_sessions + 1; end if;
    if v_pb and not s.is_new_pb then
      update sessions set is_new_pb = true where id = s.id;
      v_pbs := v_pbs + 1;
    end if;
  end loop;

  return query select v_sessions, v_results, v_pbs;
end $$;

-- Run from the SQL editor only, never from the app.
revoke all on function backfill_test_results() from public, anon, authenticated;
revoke all on function ranking_tests(uuid) from public, anon;
grant execute on function ranking_tests(uuid) to authenticated;

commit;

-- MARK: - Run the back-fill (shows how many posts, results and PBs it added)

select * from backfill_test_results();


-- ################################################################################
-- docs/migrations/2026-11-13-performance-indexes.sql
-- ################################################################################
-- Performance indexes (2026-11-13). Run once in the Supabase SQL editor, staging first. Safe to run
-- again. Run on staging 2026-11-14 (dry run rolled back first); not yet on production. Changes no data and no behaviour: each index serves a lookup the app already makes, which
-- today reads the whole table. On staging, pg_stat_user_tables showed profiles scanned whole
-- 345,726 times (against 47,561 index scans) and test_results 16,438 times (against 992).
--
-- On a project with real traffic, run each statement on its own with CONCURRENTLY added
-- (`create index concurrently if not exists …`) so writes aren't held while it builds; CONCURRENTLY
-- can't run inside begin/commit, which is why this file has none.

-- Everyone in a club: clubmates (ViewerContext), the members list (CalendarService.members), the
-- coach's Rowers list, club ranks, challenge standings, Rankings.
create index if not exists profiles_club_id_idx on profiles (club_id);

-- Someone's followers and follow requests (FollowService), follower counts on Profile.
-- The primary key (follower_id, followee_id) only serves "who I follow".
create index if not exists follows_followee_status_idx on follows (followee_id, status);

-- A rower's test results: Profile's personal bests, PB history, Rankings' Tests, predictions'
-- test pieces, the coach's 2k column. The existing index leads with distance_key for leaderboards.
create index if not exists test_results_user_distance_idx on test_results (user_id, distance_key);

-- A post's test results (the workout's result banner), and deleting a post, whose cascade
-- otherwise reads all of test_results.
create index if not exists test_results_session_idx on test_results (session_id);

-- The posts rowed for a coach's workout (workout results, the notepad's posted splits).
create index if not exists sessions_workout_idx on sessions (workout_id) where workout_id is not null;

-- A practice's register history (CalendarService.markLog), newest change last.
create index if not exists attendance_mark_log_practice_idx on attendance_mark_log (practice_id, set_at);


-- ################################################################################
-- docs/migrations/2026-11-17-private-posts.sql
-- ################################################################################
-- Private posts (decision 106, user 2026-11-17). Run once in the Supabase SQL editor, staging
-- first, BEFORE installing the build that needs it (the app reads sessions.is_private). Safe to
-- run again.
--
-- A rower can make a post they've already put up private, one at a time, and visible again.
-- While a post is private:
--   * only its owner can read it — not followers, clubmates, or a coach of their club (the user
--     chose "hidden from coach too"), so it leaves the Feed, other people's view of the profile,
--     a coach's set-workout results and the rower pages coaches open;
--   * its test result is off the test leaderboards and others' PB tiles and club ranks, and its
--     metres are off the volume leaderboards, challenges, weekly rank alerts and Season Wrapped's
--     club comparisons (daily_totals.ranked_* lose them, and get them back when it's visible);
--   * it's off an erg event's board;
--   * the owner still counts it everywhere that's theirs alone: own totals, streak, PBs and
--     predictions.
-- Making a post private also removes other people's notifications about it, so nobody is left
-- holding a link to a post they can't open. Making it visible again doesn't bring them back.

begin;

-- MARK: - 1. The flag

alter table sessions add column if not exists is_private boolean not null default false;

-- Only set_session_private() changes it, so the leaderboard totals always move with it. A new
-- post is never private (it goes up visible; the owner makes it private afterwards).
create or replace function sessions_guard_private()
returns trigger language plpgsql set search_path = public as $$
begin
  if tg_op = 'INSERT' then
    new.is_private := false;
  elsif new.is_private is distinct from old.is_private
        and coalesce(current_setting('rp.private_change', true), '') <> 'on' then
    new.is_private := old.is_private;
  end if;
  return new;
end $$;

drop trigger if exists sessions_guard_private on sessions;
create trigger sessions_guard_private
  before insert or update of is_private on sessions
  for each row execute function sessions_guard_private();

-- MARK: - 2. Who can read a private post: its owner only

-- As 2026-11-03-mutual-follow-posts.sql, with "and not s.is_private" for everyone but the owner.
-- This also stops others reacting to or commenting on it (the restrictive insert policies).
create or replace function can_view_session(sid uuid)
returns boolean
language sql stable security definer set search_path = public as $$
  select coalesce((
    select s.user_id = auth.uid()
      or (
        not s.is_private
        and not exists (
          select 1 from blocks b
          where (b.blocker_id = auth.uid() and b.blocked_id = s.user_id)
             or (b.blocker_id = s.user_id and b.blocked_id = auth.uid())
        )
        and (
          not author.is_private
          or exists (
            select 1 from follows f
            where f.follower_id = auth.uid() and f.followee_id = s.user_id and f.status = 'accepted'
          )
        )
        and (
          (s.visibility in ('following', 'everyone')
           and exists (
             select 1 from follows f
             where f.follower_id = auth.uid() and f.followee_id = s.user_id and f.status = 'accepted'
           )
           and exists (
             select 1 from follows f
             where f.follower_id = s.user_id and f.followee_id = auth.uid() and f.status = 'accepted'
           ))
          or (s.visibility in ('club', 'everyone')
              and author.club_id is not null
              and author.club_id = (select viewer.club_id from profiles viewer where viewer.id = auth.uid()))
        )
      )
    from sessions s
    join profiles author on author.id = s.user_id
    where s.id = sid
  ), false);
$$;

-- As 2026-10-05-coaching.sql, but a coach no longer sees a private post either.
create or replace function can_read_session(sid uuid)
returns boolean
language sql stable security definer set search_path = public as $$
  select coalesce((
    select s.user_id = auth.uid()
      or (not s.is_private and (can_view_session(sid) or coaches_rower(s.user_id)))
    from sessions s where s.id = sid
  ), false);
$$;

-- A post's test result follows the post: others can't read it while the post is private (the owner
-- still reads their own through own_row).
create or replace function session_is_private(sid uuid)
returns boolean
language sql stable security definer set search_path = public as $$
  select coalesce((select s.is_private from sessions s where s.id = sid), false);
$$;
revoke all on function session_is_private(uuid) from public, anon;
grant execute on function session_is_private(uuid) to authenticated;

drop policy if exists read_visible on test_results;
create policy read_visible on test_results for select to authenticated
  using (can_view_user(user_id) and not session_is_private(session_id));

-- MARK: - 3. Making a post private, or visible again

create or replace function set_session_private(p_session uuid, p_private boolean)
returns void
language plpgsql security definer set search_path = public as $$
declare
  s sessions%rowtype;
  ranked_m int;
  change int;
begin
  select * into s from sessions where id = p_session for update;
  if not found or s.user_id is distinct from auth.uid() then
    raise exception 'You can only change your own posts.';
  end if;
  if s.is_private = p_private then return; end if;

  -- Its leaderboard metres come off while it's private and go back when it's visible.
  ranked_m := case when coalesce(s.is_ranked, false) then s.total_distance_m else 0 end;
  if ranked_m > 0 then
    change := case when p_private then -ranked_m else ranked_m end;
    update daily_totals set
      ranked_distance_m     = greatest(0, ranked_distance_m + change),
      ranked_erg_distance_m = greatest(0, ranked_erg_distance_m + change)
    where user_id = s.user_id and day = s.session_date;
  end if;

  perform set_config('rp.private_change', 'on', true);
  update sessions set is_private = p_private where id = p_session;
  perform set_config('rp.private_change', 'off', true);

  if p_private then
    delete from notifications where session_id = p_session and recipient_id <> s.user_id;
  end if;
end $$;
revoke all on function set_session_private(uuid, boolean) from public, anon;
grant execute on function set_session_private(uuid, boolean) to authenticated;

-- MARK: - 4. Deleting a private post

-- As 2026-10-15-delete-posts.sql, except a private post's leaderboard metres already came off when
-- it was made private, so they aren't taken off twice.
create or replace function delete_session(p_session uuid)
returns text[]
language plpgsql security definer set search_path = public as $$
declare
  s sessions%rowtype;
  paths text[];
  ranked_m int;
begin
  select * into s from sessions where id = p_session;
  if not found or s.user_id is distinct from auth.uid() then
    raise exception 'You can only delete your own posts.';
  end if;

  select coalesce(array_agg(p), '{}') into paths from (
    select monitor_photo_path as p from segments
      where session_id = p_session and monitor_photo_path is not null
    union all
    select path from session_photos where session_id = p_session
  ) photos;

  ranked_m := case when coalesce(s.is_ranked, false) and not s.is_private then s.total_distance_m else 0 end;
  update daily_totals set
    distance_m            = greatest(0, distance_m - s.total_distance_m),
    erg_distance_m        = greatest(0, erg_distance_m - s.total_distance_m),
    session_count         = greatest(0, session_count - 1),
    ranked_distance_m     = greatest(0, ranked_distance_m - ranked_m),
    ranked_erg_distance_m = greatest(0, ranked_erg_distance_m - ranked_m)
  where user_id = s.user_id and day = s.session_date;
  -- A day with nothing left on it goes, so it no longer counts for the streak.
  delete from daily_totals
  where user_id = s.user_id and day = s.session_date and session_count <= 0;

  delete from sessions where id = p_session;
  return paths;
end $$;
revoke all on function delete_session(uuid) from public, anon;
grant execute on function delete_session(uuid) to authenticated;

-- MARK: - 5. Erg event boards

-- As 2026-10-18-challenges-and-erg-events.sql, leaving out private posts.
create or replace function erg_event_board(p_event uuid)
returns table (user_id uuid, display_name text, gender rower_gender, category rower_category,
               distance_m int, time_ms int, session_id uuid)
language plpgsql stable security definer set search_path = public as $$
declare
  e erg_events;
begin
  select * into e from erg_events where id = p_event;
  if e.id is null or e.club_id is distinct from (select p.club_id from profiles p where p.id = auth.uid()) then
    return;
  end if;
  return query
    select distinct on (s.user_id)
           s.user_id, p.display_name, p.gender, p.category, g.distance_m, g.time_ms, s.id
    from sessions s
    join profiles p on p.id = s.user_id and p.club_id = e.club_id and p.is_rower
    join lateral (
      select x.distance_m, x.time_ms from segments x
      where x.session_id = s.id
      order by x.is_lead desc, (x.label = 'main') desc, x.position
      limit 1
    ) g on true
    where s.erg_event_id = e.id
      and not s.is_private
      -- Photographed pieces only, as for tests: a manual entry can't be checked.
      and s.photo_verified
      and s.posted_at >= e.starts_at and s.posted_at <= e.ends_at + interval '6 hours'
      and (
        (e.distance_m is not null and g.distance_m = e.distance_m)
        or (e.duration_ms is not null
            and abs(g.time_ms - e.duration_ms) <= greatest(least(2000, e.duration_ms / 20), e.duration_ms / 100))
      )
    order by s.user_id,
             case when e.distance_m is not null then g.time_ms else -g.distance_m end;
end $$;
revoke all on function erg_event_board(uuid) from public, anon;
grant execute on function erg_event_board(uuid) to authenticated;

commit;

-- The API sees the new column and function straight away.
notify pgrst, 'reload schema';


-- ################################################################################
-- docs/migrations/2026-11-17-minimum-age.sql
-- ################################################################################
-- Minimum age 13, and protections for juniors (decision 107, user 2026-11-17). Run once in the
-- Supabase SQL editor, staging first, BEFORE installing the build that needs it (coaches read
-- rowers' details through coach_athlete_details). Safe to run again.
--
-- 1. A date of birth that makes someone under 13 can't be saved, and once given it can be changed
--    but not removed. (The app asks everyone for it: at sign-up, or once when they next open the
--    app. Someone under 13 is refused at sign-up, or their account is deleted.)
-- 2. Under 18 when they first give it: their account is made private (they can open it up again
--    in Settings).
-- 3. A junior's bodyweight is hidden from their club's coaches unless they've turned on "My parent
--    or guardian agrees". Coaches now read rowers' date of birth and bodyweight through
--    coach_athlete_details(), which applies that rule; they can no longer read the table directly.
--    A rower who hasn't given their date of birth yet is treated as a junior until they do.

begin;

-- MARK: - 1. The guardian's agreement

alter table athlete_private add column if not exists guardian_agrees_weight boolean not null default false;

-- MARK: - 2. Age rules on the date of birth

create or replace function athlete_private_age_rules()
returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if tg_op = 'UPDATE' and old.birth_date is not null and new.birth_date is null then
    raise exception 'Your date of birth can be changed but not removed.';
  end if;
  if new.birth_date is not null and new.birth_date > (current_date - interval '13 years')::date then
    raise exception 'Rowing Pals is for people 13 and over.';
  end if;
  -- A junior's account starts private: the first time a date of birth under 18 is given.
  if new.birth_date is not null
     and (tg_op = 'INSERT' or old.birth_date is null)
     and new.birth_date > (current_date - interval '18 years')::date then
    update profiles set is_private = true where id = new.user_id;
  end if;
  return new;
end $$;

drop trigger if exists athlete_private_age_rules on athlete_private;
create trigger athlete_private_age_rules
  before insert or update on athlete_private
  for each row execute function athlete_private_age_rules();

-- MARK: - 3. What coaches see

drop policy if exists coach_read on athlete_private;

create or replace function coach_athlete_details(p_users uuid[])
returns table (user_id uuid, birth_date date, weight_kg numeric)
language sql stable security definer set search_path = public as $$
  select a.user_id,
         a.birth_date,
         case
           when a.birth_date is not null
                and (a.birth_date <= (current_date - interval '18 years')::date or a.guardian_agrees_weight)
             then a.weight_kg
         end
  from athlete_private a
  where a.user_id = any(coalesce(p_users, '{}'))
    and coaches_rower(a.user_id);
$$;
revoke all on function coach_athlete_details(uuid[]) from public, anon;
grant execute on function coach_athlete_details(uuid[]) to authenticated;

commit;

-- The API sees the new column and function straight away.
notify pgrst, 'reload schema';


-- ################################################################################
-- docs/migrations/2026-11-17-verification-admin.sql
-- ################################################################################
-- Club verification decided in the app (decision 108, user 2026-11-17). Run once in the Supabase
-- SQL editor, staging first. Safe to run again.
--
-- Until now verification requests (decision 98) were decided only here, with
-- approve_club_verification('<club id>'). This adds app admins — people allowed to decide them in
-- the app, under Settings → Club verifications — and the functions that screen uses. Admins are
-- listed in app_admins, which nobody can read or change from the app: you add and remove them here.
-- The SQL-editor functions keep working.
--
-- After running it, make yourself an admin (one line, below the commit).

begin;

-- MARK: - 1. Who the app admins are

create table if not exists app_admins (
  user_id  uuid primary key references profiles on delete cascade,
  added_at timestamptz not null default now()
);
-- No policies: the app can't read or write it; only the functions below look at it.
alter table app_admins enable row level security;

create or replace function is_app_admin()
returns boolean
language sql stable security definer set search_path = public as $$
  select exists (select 1 from app_admins where user_id = auth.uid());
$$;

-- MARK: - 2. The list an admin sees

-- Every application (newest first, waiting ones before decided ones in the app), and every
-- verified club, with who asked and what they wrote.
create or replace function admin_club_verifications()
returns table (
  club_id uuid, club_name text, location text, member_count int,
  requested_by_name text, requested_by_username text, message text,
  status text, is_verified boolean, created_at timestamptz, decided_at timestamptz
)
language plpgsql stable security definer set search_path = public as $$
begin
  if not is_app_admin() then
    raise exception 'Only the app''s admins can see club verifications.';
  end if;
  return query
    select c.id, c.name, c.location,
           (select count(*)::int from profiles m where m.club_id = c.id),
           p.display_name, p.username, r.message,
           case when c.is_verified then 'approved' else coalesce(r.status, 'none') end,
           c.is_verified, coalesce(r.created_at, c.verified_at, c.created_at), coalesce(r.decided_at, c.verified_at)
    from clubs c
    left join club_verification_requests r on r.club_id = c.id
    left join profiles p on p.id = r.requested_by
    where r.club_id is not null or c.is_verified
    order by coalesce(r.created_at, c.verified_at, c.created_at) desc;
end $$;

-- MARK: - 3. Deciding

-- 'approve' gives the club the verified tag; 'decline' turns the application down (the owner can
-- apply again); 'remove' takes the tag away again.
create or replace function admin_decide_club_verification(p_club uuid, p_decision text)
returns void
language plpgsql security definer set search_path = public as $$
begin
  if not is_app_admin() then
    raise exception 'Only the app''s admins can decide club verifications.';
  end if;
  case p_decision
    when 'approve' then perform approve_club_verification(p_club);
    when 'decline' then perform decline_club_verification(p_club);
    when 'remove'  then perform remove_club_verification(p_club);
    else raise exception 'Unknown decision: %', p_decision;
  end case;
end $$;

do $$
declare
  f text;
begin
  foreach f in array array[
    'is_app_admin()', 'admin_club_verifications()', 'admin_decide_club_verification(uuid, text)'
  ] loop
    execute format('revoke all on function %s from public, anon', f);
    execute format('grant execute on function %s to authenticated', f);
  end loop;
end $$;

commit;

-- The API sees the new functions straight away.
notify pgrst, 'reload schema';

-- MARK: - Make yourself an admin (run once, with your own username)
--
-- insert into app_admins (user_id)
-- select id from profiles where username = 'piero'
-- on conflict do nothing;
--
-- To remove an admin:  delete from app_admins where user_id = (select id from profiles where username = '...');


-- Done. Next: section 2, step 5 of docs/production/app-store-launch.md (make yourself admin).
